export const arkade_kitties = "// ArkadeKitties - Simplified Breeding Contract\n// Demonstrates commit-reveal breeding with oracle randomness\n//\n// Key features demonstrated:\n// - group.isFresh: Detect newly minted kitties\n// - group.controlIs: Verify species membership\n// - group.metadataHash: Verify genome/attributes\n// - group.delta: Detect minting vs transfer\n//\n// Asset hierarchy:\n// - speciesControlId: The \"species\" control asset (e.g., \"ArkadeKitties\")\n// - Each kitty is a unique asset controlled by speciesControlId\n// - Breeding creates a new kitty with isFresh=1\n\nimport \"single_sig.ark\";\n\ncontract ArkadeKitties(\n    bytes32 speciesControlIdTxid,\n    int speciesControlIdGidx,\n    pubkey oraclePk,\n    int exit\n) {\n    // Breed two kitties to create a new one\n    // Parents must be species-controlled, child must be fresh\n    function breed(\n        bytes32 sireIdTxid,\n        int sireIdGidx,\n        bytes32 dameIdTxid,\n        int dameIdGidx,\n        bytes32 childIdTxid,\n        int childIdGidx,\n        bytes32 sireGenomeHash,\n        bytes32 dameGenomeHash,\n        bytes32 expectedChildMetadataHash,\n        signature oracleSig,\n        int childOutputIdx,\n        int sireOutputIdx,\n        int dameOutputIdx,\n        int ctrlOutputIdx\n    ) {\n        // Verify sire is species-controlled with correct genome\n        let sireGroup = tx.assetGroups.find(sireIdTxid, sireIdGidx);\n        require(sireGroup.controlIs(speciesControlIdTxid, speciesControlIdGidx), \"sire not species-controlled\");\n        require(sireGroup.metadataHash == sireGenomeHash, \"sire genome mismatch\");\n        require(sireGroup.delta == 0, \"sire must be retained\");\n\n        // Verify dame is species-controlled with correct genome\n        let dameGroup = tx.assetGroups.find(dameIdTxid, dameIdGidx);\n        require(dameGroup.controlIs(speciesControlIdTxid, speciesControlIdGidx), \"dame not species-controlled\");\n        require(dameGroup.metadataHash == dameGenomeHash, \"dame genome mismatch\");\n        require(dameGroup.delta == 0, \"dame must be retained\");\n\n        // Verify child is fresh (new issuance in this tx)\n        let childGroup = tx.assetGroups.find(childIdTxid, childIdGidx);\n        require(childGroup.isFresh == 1, \"child must be fresh\");\n        require(childGroup.delta == 1, \"must mint exactly 1 child\");\n        require(childGroup.controlIs(speciesControlIdTxid, speciesControlIdGidx), \"child not species-controlled\");\n        require(childGroup.metadataHash == expectedChildMetadataHash, \"child genome mismatch\");\n\n        // Species control must be retained (delta == 0)\n        let ctrlGroup = tx.assetGroups.find(speciesControlIdTxid, speciesControlIdGidx);\n        require(ctrlGroup.delta == 0, \"species control must be retained\");\n\n        // Oracle signature validates the breeding (genome combination)\n        require(checkSig(oracleSig, oraclePk), \"invalid oracle sig\");\n\n        // Verify outputs contain all assets\n        require(tx.outputs[childOutputIdx].assets.lookup(childIdTxid, childIdGidx) == 1, \"child not in output\");\n        require(tx.outputs[sireOutputIdx].assets.lookup(sireIdTxid, sireIdGidx) == 1, \"sire not returned\");\n        require(tx.outputs[dameOutputIdx].assets.lookup(dameIdTxid, dameIdGidx) == 1, \"dame not returned\");\n        require(tx.outputs[ctrlOutputIdx].assets.lookup(speciesControlIdTxid, speciesControlIdGidx) == 1, \"ctrl not retained\");\n    }\n\n    // Transfer a kitty to a new owner\n    function transfer(bytes32 kittyIdTxid, int kittyIdGidx, pubkey newOwnerPk, signature ownerSig, pubkey ownerPk) {\n        let kittyGroup = tx.assetGroups.find(kittyIdTxid, kittyIdGidx);\n\n        // Must be existing kitty (not fresh)\n        require(kittyGroup.isFresh == 0, \"must be existing kitty\");\n\n        // Must be species-controlled\n        require(kittyGroup.controlIs(speciesControlIdTxid, speciesControlIdGidx), \"not species-controlled\");\n\n        // Must be transfer (delta == 0)\n        require(kittyGroup.delta == 0, \"must be transfer only\");\n\n        require(tx.outputs[0].assets.lookup(kittyIdTxid, kittyIdGidx) == 1, \"kitty not in output\");\n        require(tx.outputs[0].scriptPubKey == new SingleSig(newOwnerPk, exit), \"wrong destination\");\n        require(checkSig(ownerSig, ownerPk), \"invalid owner sig\");\n    }\n}\n";

export const bond_mint = "// BondMint Contract\n//\n// Per-issuance collateral vault holding the borrower's debit tokens. Created\n// atomically by RepaymentPool.issue. Each vault represents one issuance of\n// `mintedAmount` credit + `mintedAmount` debit (1:1) by a borrower against\n// `collateral` sats, maturing at block height `maturity`.\n//\n// SETTLEMENT PATHS (four; all burn the vault's debit exactly)\n//   repay      — pre-maturity, borrower-signed. The borrower pays par USDT,\n//                takes their collateral back.\n//   liquidate  — pre-maturity MARGIN CALL, permissionless. Triggered when\n//                `collateralValue < liqThresholdBps × mintedAmount / 10000`\n//                at the pool. Oracle-priced sale; collateral → auctioneer;\n//                USDT → pool. This is what keeps every vault in the pool\n//                covenant-thresholded healthy at every block — the invariant\n//                that makes credit tokens genuinely fungible.\n//   auction    — post-maturity DEFAULT, permissionless, in the auction window.\n//                Same oracle-priced sale.\n//   roll       — pre-maturity, borrower-signed. Authorises migration of this\n//                vault to a NEXT-maturity pool in a single atomic tx (paired\n//                with RepaymentPool.rollOut on this pool and rollIn on the\n//                new pool, plus a non_interactive_swap fill that bridges the\n//                USDT discharge). See docs/bonds.md §Loan roll.\n//\n// PHASED TIMELINE\n//   [-, maturity)                              REPAY phase    vault.repay,\n//                                                             vault.liquidate,\n//                                                             vault.roll\n//   [maturity, maturity + auctionWindow)        AUCTION phase  vault.auction\n//   [maturity + auctionWindow, +)               REDEEM phase   no vault function\n//\n// PERMISSIONLESS SETTLEMENT\n//   Each settlement-side function's debit-burn check is STRICT equality\n//   (`sumInputs == sumOutputs + mintedAmount`), so an attacker cannot batch\n//   multiple vault inputs into one settlement tx: each vault's individual\n//   check requires the global debit delta to equal THAT vault's mintedAmount\n//   exactly, which fails closed for any multi-vault combination. The pool\n//   side enforces the same strict equality symmetrically.\n//\n//   Within the pre-maturity phase, the right pairing is enforced by a\n//   combination of per-function output-pin conflicts AND pool-side borrower\n//   signatures on every state-transition pool function:\n//     - vault.repay         pins output[1]=borrower; pool.acceptRepayment\n//                           pins output[1]=borrower (same dest, no conflict)\n//                           — and borrower-signs the spend so non-consensual\n//                           pairings are blocked.\n//     - vault.liquidate     pins output[1]=auctioneer; pool.liquidate pins\n//                           output[1]=auctioneer (same dest, no conflict)\n//                           — pool side health-gates via oracle, so a\n//                           healthy vault cannot be liquidated.\n//     - vault.roll          pins NO output (it just authorises the spend);\n//                           the paired pool.rollOut REQUIRES the borrower's\n//                           signature too. Without the pool-side sig, an\n//                           attacker could pair the permissionless\n//                           vault.liquidate with rollOut and force-liquidate\n//                           a healthy vault at par. rollOut's sig blocks\n//                           that pairing.\n//\n//   Auctioneer identity is a witness pubkey; they pin their own collateral\n//   destination by signing the tx they construct.\n//\n// POOL-AUTHENTICATION CAVEAT\n//   The \"genuine pool not co-spent\" check verifies only that an input holds\n//   the debit-control asset (`tx.inputs[poolIdx].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx)\n//   >= 1`), not that the input's scriptPubKey is the canonical RepaymentPool\n//   covenant. Safety therefore rests on the asset-registry invariant that\n//   no pool function ever lets debitCtrlId leak from its output[0]. EVERY\n//   future pool function MUST retain debitCtrlId. The regression test\n//   `test_pool_retains_debit_ctrl_in_every_function` enforces this at the\n//   ASM level — do not delete it.\n//\n// UNILATERAL EXIT (Arkade operator offline, after `<exit>` blocks)\n//   Exit signers come from the function's pubkey parameters. In practice the\n//   borrower is the only relevant signer for unilateral collateral recovery.\n//   See docs/bonds.md §\"Unilateral exits\".\n\nimport \"single_sig.ark\";\n\ncontract BondMint(\n  pubkey  borrowerPk,\n  bytes32 debitAssetIdTxid,\n  int     debitAssetIdGidx,\n  bytes32 debitCtrlIdTxid,\n  int     debitCtrlIdGidx,\n  int     mintedAmount,\n  int     collateral,\n  int     maturity,\n  int     auctionWindow,\n  int     exit\n) {\n\n  // REPAY — pre-maturity, atomic with RepaymentPool.acceptRepayment.\n  //   output[0]: pool re-created (enforced by acceptRepayment)\n  //   output[1]: collateral sats → borrower\n  function repay(signature borrowerSig, int poolIdx) {\n    require(checkSig(borrowerSig, borrowerPk), \"invalid borrower sig\");\n    require(tx.time < maturity, \"loan matured\");\n\n    require(tx.inputs[poolIdx].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"genuine pool not co-spent\");\n\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.sumInputs == debitGroup.sumOutputs + mintedAmount, \"debit not burned exactly mintedAmount\");\n\n    require(tx.outputs[1].value >= collateral, \"collateral not returned\");\n    require(tx.outputs[1].scriptPubKey == new SingleSig(borrowerPk, exit), \"output 1 not borrower\");\n  }\n\n  // LIQUIDATE — pre-maturity MARGIN CALL, permissionless. The pool's liquidate\n  // does the oracle + threshold + payout math; this script authorises the\n  // spend (time gate + pool co-spent + debit burn) and pins the collateral\n  // output to the auctioneer.\n  //   output[0]: pool re-created (enforced by acceptAuction-style pool.liquidate)\n  //   output[1]: collateral (or sold portion) → auctioneer\n  //\n  // DEFENSE-IN-DEPTH: output[1].value > 0 ensures *something* flows to the\n  // auctioneer-pinned output. The exact value (collateralSold or all\n  // collateral, depending on over-cover/shortfall) is enforced by the\n  // co-spent pool.liquidate. If that pool-side check ever regresses, this\n  // vault-side floor still prevents the \"1 sat to auctioneer, rest as miner\n  // fee\" siphon shape.\n  function liquidate(int poolIdx, pubkey auctioneerPk) {\n    require(tx.time < maturity, \"matured; use auction\");\n\n    require(tx.inputs[poolIdx].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"genuine pool not co-spent\");\n\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.sumInputs == debitGroup.sumOutputs + mintedAmount, \"debit not burned exactly mintedAmount\");\n\n    require(tx.outputs[1].value > 0, \"auctioneer output empty\");\n    require(tx.outputs[1].scriptPubKey == new SingleSig(auctioneerPk, exit), \"output 1 not auctioneer\");\n  }\n\n  // AUCTION — during the auction window, atomic with RepaymentPool.acceptAuction.\n  // Permissionless: any auctioneer constructs the tx and specifies their own\n  // collateral destination via `auctioneerPk`.\n  //   output[0]: pool re-created (enforced by acceptAuction)\n  //   output[1]: collateral (or sold portion) → auctioneer\n  function auction(int poolIdx, pubkey auctioneerPk) {\n    require(tx.time >= maturity, \"not yet matured\");\n    int windowEnd = maturity + auctionWindow;\n    require(tx.time < windowEnd, \"auction window closed\");\n\n    require(tx.inputs[poolIdx].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"genuine pool not co-spent\");\n\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.sumInputs == debitGroup.sumOutputs + mintedAmount, \"debit not burned exactly mintedAmount\");\n\n    require(tx.outputs[1].value > 0, \"auctioneer output empty\");\n    require(tx.outputs[1].scriptPubKey == new SingleSig(auctioneerPk, exit), \"output 1 not auctioneer\");\n  }\n\n  // ROLL — borrower-signed authorisation to migrate this vault to a next-\n  // maturity pool. Pre-maturity, atomic with RepaymentPool.rollOut on the\n  // OLD pool (this vault's pool) and RepaymentPool.rollIn on the NEW pool.\n  // The borrower's signature is the consent gate; the old pool's rollOut\n  // enforces that the obligation is discharged (USDT inflow ≥ mintedAmount);\n  // the new pool's rollIn enforces that the new vault is properly\n  // collateralised. This script just authorises the spend and burns the\n  // old debit. The collateral input is released into the tx — the paired\n  // rollIn must claim it into a new BondMint output, or the tx fails closed.\n  //\n  //   output[0..]: free (rollOut + rollIn + swap pin their own outputs at\n  //                witness-supplied indices)\n  function roll(signature borrowerSig, int poolIdx) {\n    require(checkSig(borrowerSig, borrowerPk), \"invalid borrower sig\");\n    require(tx.time < maturity, \"vault matured\");\n\n    require(tx.inputs[poolIdx].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"genuine pool not co-spent\");\n\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.sumInputs == debitGroup.sumOutputs + mintedAmount, \"debit not burned exactly mintedAmount\");\n  }\n\n  // UNILATERAL EXIT (CSV)\n  // Borrower recovers collateral after exit delay (Arkade operator offline).\n  function unilateral(signature borrowerSig) tapscript {\n    require(older(exit));\n    require(checkSig(borrowerSig, borrowerPk));\n  }\n}\n";

export const repayment_pool = "// RepaymentPool Contract\n//\n// Per-maturity singleton implementing a fixed-maturity bond market: borrowers\n// self-issue credit + debit tokens (1:1) against collateral; the credit half\n// is sold by the borrower for USDT on the order book (via non_interactive_swap)\n// — that is the borrower's loan and the lender's entry point. NO interest rate;\n// the yield is whatever discount the market sets at sale time.\n//\n// Two settlement paths close a vault outside of voluntary repayment:\n//\n//   MARGIN CALL (pre-maturity, permissionless)\n//     `liquidate` fires the moment `collateralValue < liqThresholdBps ×\n//     mintedAmount / 10000`. The vault's collateral is sold at the oracle\n//     price, USDT enters the pool, the obligation is extinguished. This keeps\n//     every vault in the pool thresholded healthy at every block, which is\n//     what preserves credit-token fungibility on the order book: a lender\n//     buying credit doesn't need to know WHICH vault backs it because every\n//     vault in the pool is covenant-guaranteed to be above the health floor.\n//\n//   AUCTION (post-maturity default, permissionless)\n//     `acceptAuction` closes vaults whose borrowers did not repay by maturity.\n//     Same oracle-priced sale, same auctioneer-discount incentive. Only fires\n//     in the dedicated auction window so it can't race with redemptions.\n//\n// PHASED TIMELINE\n//   [-, maturity)                              REPAY    issue, acceptRepayment,\n//                                                       rollOut, rollIn,\n//                                                       liquidate (margin call)\n//   [maturity, maturity + auctionWindow)        AUCTION  acceptAuction only\n//   [maturity + auctionWindow, +)               REDEEM   redeem only\n//\n// UNILATERAL EXIT (Arkade operator offline, after `<exit>` blocks)\n//   - BondMint per-vault: collateral recoverable cooperatively or unilaterally\n//     via N-of-N + CSV; the surviving signer is the borrower\n//     (single-owner-effective on the unilateral path).\n//   - RepaymentPool aggregate: the REDEEM phase drains the pool into\n//     per-holder SingleSig UTXOs — each of those has a clean single-owner\n//     exit, so the lasting on-chain state after every holder redeems is\n//     fully self-sovereign and the pool's aggregate exit surface goes to\n//     zero. See docs/bonds.md §\"Unilateral exits\".\n//\n// STATE carried forward on every spend:\n//   usdtBalance, totalCreditOutstanding, totalDebitOutstanding\n\nimport \"bond_mint.ark\";\n\ncontract RepaymentPool(\n  bytes32 usdtAssetIdTxid,\n  int     usdtAssetIdGidx,\n  bytes32 creditAssetIdTxid,     // fungible per-maturity credit (lender entitlement)\n  int     creditAssetIdGidx,\n  bytes32 creditCtrlIdTxid,      // control asset gating credit mint\n  int     creditCtrlIdGidx,\n  bytes32 debitAssetIdTxid,      // fungible per-maturity debit (borrower obligation)\n  int     debitAssetIdGidx,\n  bytes32 debitCtrlIdTxid,       // control asset gating debit mint\n  int     debitCtrlIdGidx,\n  bytes32 ticker,                // oracle feed id (e.g. sha256(\"BTC/USDT\"))\n  pubkey  oraclePk,              // price oracle (Fuji-style signed feed)\n  int     oracleMaxAgeSeconds,   // max oracle staleness, in SECONDS (tx.offchainTime); contrast with maturity/auctionWindow which are BLOCK HEIGHTS (tx.time)\n  int     initRatioBps,          // required collateral ratio at issuance (e.g. 15000 = 150%)\n  int     liqThresholdBps,       // margin-call trigger: liquidate when collateralValue < this × mintedAmount / 10000 (e.g. 11000 = 110%)\n  int     maturity,              // block height: settlement boundary\n  int     auctionWindow,         // blocks: auction phase length post-maturity\n  int     auctionDiscountBps,    // bps: auctioneer's spread on pool income (0..10000)\n  int     usdtBalance,\n  int     totalCreditOutstanding,\n  int     totalDebitOutstanding,\n  int     exit\n) {\n\n  // ISSUE — pre-maturity, borrower mints `amount` credit + `amount` debit (1:1)\n  // and posts collateral. Credit → borrower's wallet (to sell). Debit → a new\n  // BondMint vault that locks the collateral.\n  //   output[0]: pool re-created (totalCredit + amount, totalDebit + amount)\n  //   output[1]: `amount` credit → borrower\n  //   output[2]: BondMint vault holding collateral + `amount` debit\n  function issue(int amount, int collateral, pubkey borrowerPk, signature borrowerSig, int oraclePrice, int oracleTime, signature oracleSig) {\n    require(amount > 0, \"zero issuance\");\n    require(collateral > 0, \"zero collateral\");\n    require(initRatioBps > liqThresholdBps, \"liq threshold must be below init ratio\");\n    require(liqThresholdBps > 0, \"liq threshold must be positive\");\n    require(auctionWindow > 0, \"auction window must be positive\");\n    require(auctionDiscountBps >= 0, \"negative discount\");\n    require(auctionDiscountBps < 10000, \"discount >= 100%\");\n    require(tx.time < maturity, \"pool matured\");\n    require(checkSig(borrowerSig, borrowerPk), \"invalid borrower sig\");\n    require(oraclePrice > 0, \"invalid oracle price\");\n\n    int oracleAge = tx.offchainTime - oracleTime;\n    require(oracleAge >= 0, \"future-dated oracle\");\n    require(oracleAge <= oracleMaxAgeSeconds, \"stale oracle\");\n    let oracleMsg = sha256(ticker + oraclePrice + oracleTime);\n    require(checkSigFromStack(oracleSig, oraclePk, oracleMsg), \"invalid oracle signature\");\n\n    int collateralValue = collateral * oraclePrice / 100000000;\n    int required = (amount * initRatioBps + 9999) / 10000;\n    require(collateralValue >= required, \"undercollateralized at issuance\");\n\n    let creditGroup = tx.assetGroups.find(creditAssetIdTxid, creditAssetIdGidx);\n    require(creditGroup.delta == amount, \"credit delta mismatch\");\n    require(creditGroup.controlIs(creditCtrlIdTxid, creditCtrlIdGidx), \"wrong credit control\");\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.delta == amount, \"debit delta mismatch\");\n    require(debitGroup.controlIs(debitCtrlIdTxid, debitCtrlIdGidx), \"wrong debit control\");\n    let ccGroup = tx.assetGroups.find(creditCtrlIdTxid, creditCtrlIdGidx);\n    require(ccGroup.delta == 0, \"credit control changed\");\n    let dcGroup = tx.assetGroups.find(debitCtrlIdTxid, debitCtrlIdGidx);\n    require(dcGroup.delta == 0, \"debit control changed\");\n\n    int creditNext = totalCreditOutstanding + amount;\n    int debitNext  = totalDebitOutstanding + amount;\n\n    require(\n      tx.outputs[0].scriptPubKey == new RepaymentPool(\n        usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n        oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n        usdtBalance, creditNext, debitNext, exit\n      ),\n      \"invalid pool recreation\"\n    );\n    require(tx.outputs[0].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtBalance, \"pool usdt short\");\n    require(tx.outputs[0].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n    require(tx.outputs[0].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n\n    require(tx.outputs[1].assets.lookup(creditAssetIdTxid, creditAssetIdGidx) >= amount, \"credit not delivered\");\n    require(tx.outputs[1].scriptPubKey == new SingleSig(borrowerPk, exit), \"credit dest not borrower\");\n\n    require(\n      tx.outputs[2].scriptPubKey == new BondMint(\n        borrowerPk, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, amount, collateral, maturity, auctionWindow, exit\n      ),\n      \"invalid vault\"\n    );\n    require(tx.outputs[2].value >= collateral, \"collateral not locked\");\n    require(tx.outputs[2].assets.lookup(debitAssetIdTxid, debitAssetIdGidx) >= amount, \"debit not custodied in vault\");\n  }\n\n  // ACCEPT REPAYMENT — pre-maturity, co-spent with BondMint.repay.\n  //   input[vaultIdx]: the BondMint being repaid (validated by reconstruction)\n  //   output[0]: pool re-created (usdt + mintedAmount, totalDebit - mintedAmount)\n  //   output[1]: collateral sats → borrower\n  function acceptRepayment(pubkey borrowerPk, int vaultIdx, int mintedAmount, int collateral) {\n    require(mintedAmount > 0, \"zero amount\");\n    require(mintedAmount <= totalDebitOutstanding, \"exceeds outstanding\");\n    require(tx.time < maturity, \"matured; use acceptAuction\");\n\n    require(\n      tx.inputs[vaultIdx].scriptPubKey == new BondMint(\n        borrowerPk, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, mintedAmount, collateral, maturity, auctionWindow, exit\n      ),\n      \"vault input mismatch\"\n    );\n\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.sumInputs == debitGroup.sumOutputs + mintedAmount, \"debit not burned exactly mintedAmount\");\n    let creditGroup = tx.assetGroups.find(creditAssetIdTxid, creditAssetIdGidx);\n    require(creditGroup.delta == 0, \"credit must not move on repayment\");\n    let ccGroup = tx.assetGroups.find(creditCtrlIdTxid, creditCtrlIdGidx);\n    require(ccGroup.delta == 0, \"credit control changed\");\n    let dcGroup = tx.assetGroups.find(debitCtrlIdTxid, debitCtrlIdGidx);\n    require(dcGroup.delta == 0, \"debit control changed\");\n\n    int usdtNext  = usdtBalance + mintedAmount;\n    int debitNext = totalDebitOutstanding - mintedAmount;\n\n    require(\n      tx.outputs[0].scriptPubKey == new RepaymentPool(\n        usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n        oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n        usdtNext, totalCreditOutstanding, debitNext, exit\n      ),\n      \"invalid pool recreation\"\n    );\n    require(tx.outputs[0].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtNext, \"repayment not received\");\n    require(tx.outputs[0].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n    require(tx.outputs[0].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n\n    require(tx.outputs[1].value >= collateral, \"collateral not returned\");\n    require(tx.outputs[1].scriptPubKey == new SingleSig(borrowerPk, exit), \"collateral dest not borrower\");\n  }\n\n  // ROLL OUT — borrower co-spends their old BondMint to extinguish the\n  // old-maturity obligation.\n  function rollOut(pubkey borrowerPk, signature borrowerSig, int vaultIdx, int oldMintedAmount, int collateral,\n                   int outIdxPool, int expectedDischarge) {\n    require(oldMintedAmount > 0, \"zero amount\");\n    require(oldMintedAmount <= totalDebitOutstanding, \"exceeds outstanding\");\n    require(expectedDischarge == oldMintedAmount, \"discharge must equal par\");\n    require(tx.time < maturity, \"old pool matured\");\n    require(checkSig(borrowerSig, borrowerPk), \"invalid borrower sig\");\n\n    require(\n      tx.inputs[vaultIdx].scriptPubKey == new BondMint(\n        borrowerPk, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, oldMintedAmount, collateral, maturity, auctionWindow, exit\n      ),\n      \"vault input mismatch\"\n    );\n\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.sumInputs == debitGroup.sumOutputs + oldMintedAmount, \"debit not burned exactly oldMintedAmount\");\n    let creditGroup = tx.assetGroups.find(creditAssetIdTxid, creditAssetIdGidx);\n    require(creditGroup.delta == 0, \"credit must not move during roll\");\n    let ccGroup = tx.assetGroups.find(creditCtrlIdTxid, creditCtrlIdGidx);\n    require(ccGroup.delta == 0, \"credit control changed\");\n    let dcGroup = tx.assetGroups.find(debitCtrlIdTxid, debitCtrlIdGidx);\n    require(dcGroup.delta == 0, \"debit control changed\");\n\n    int usdtNext = usdtBalance + expectedDischarge;\n    int debitNext = totalDebitOutstanding - oldMintedAmount;\n\n    require(\n      tx.outputs[outIdxPool].scriptPubKey == new RepaymentPool(\n        usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n        oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n        usdtNext, totalCreditOutstanding, debitNext, exit\n      ),\n      \"invalid pool recreation\"\n    );\n    require(tx.outputs[outIdxPool].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtNext, \"discharge not received\");\n    require(tx.outputs[outIdxPool].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n    require(tx.outputs[outIdxPool].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n  }\n\n  // ROLL IN — borrower opens a new vault on THIS pool (the next maturity).\n  function rollIn(int newMintedAmount, int newCollateral, pubkey borrowerPk, signature borrowerSig,\n                  int oraclePrice, int oracleTime, signature oracleSig,\n                  int outIdxPool, int outIdxVault, int outIdxCredit) {\n    require(newMintedAmount > 0, \"zero issuance\");\n    require(newCollateral > 0, \"zero collateral\");\n    require(initRatioBps > liqThresholdBps, \"liq threshold must be below init ratio\");\n    require(liqThresholdBps > 0, \"liq threshold must be positive\");\n    require(auctionWindow > 0, \"auction window must be positive\");\n    require(auctionDiscountBps >= 0, \"negative discount\");\n    require(auctionDiscountBps < 10000, \"discount >= 100%\");\n    require(tx.time < maturity, \"new pool matured\");\n    require(checkSig(borrowerSig, borrowerPk), \"invalid borrower sig\");\n    require(oraclePrice > 0, \"invalid oracle price\");\n\n    int oracleAge = tx.offchainTime - oracleTime;\n    require(oracleAge >= 0, \"future-dated oracle\");\n    require(oracleAge <= oracleMaxAgeSeconds, \"stale oracle\");\n    let oracleMsg = sha256(ticker + oraclePrice + oracleTime);\n    require(checkSigFromStack(oracleSig, oraclePk, oracleMsg), \"invalid oracle signature\");\n\n    int collateralValue = newCollateral * oraclePrice / 100000000;\n    int required = (newMintedAmount * initRatioBps + 9999) / 10000;\n    require(collateralValue >= required, \"undercollateralized at issuance\");\n\n    let creditGroup = tx.assetGroups.find(creditAssetIdTxid, creditAssetIdGidx);\n    require(creditGroup.delta == newMintedAmount, \"credit delta mismatch\");\n    require(creditGroup.controlIs(creditCtrlIdTxid, creditCtrlIdGidx), \"wrong credit control\");\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.delta == newMintedAmount, \"debit delta mismatch\");\n    require(debitGroup.controlIs(debitCtrlIdTxid, debitCtrlIdGidx), \"wrong debit control\");\n    let ccGroup = tx.assetGroups.find(creditCtrlIdTxid, creditCtrlIdGidx);\n    require(ccGroup.delta == 0, \"credit control changed\");\n    let dcGroup = tx.assetGroups.find(debitCtrlIdTxid, debitCtrlIdGidx);\n    require(dcGroup.delta == 0, \"debit control changed\");\n\n    int creditNext = totalCreditOutstanding + newMintedAmount;\n    int debitNext = totalDebitOutstanding + newMintedAmount;\n\n    require(\n      tx.outputs[outIdxPool].scriptPubKey == new RepaymentPool(\n        usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n        oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n        usdtBalance, creditNext, debitNext, exit\n      ),\n      \"invalid pool recreation\"\n    );\n    require(tx.outputs[outIdxPool].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtBalance, \"pool usdt short\");\n    require(tx.outputs[outIdxPool].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n    require(tx.outputs[outIdxPool].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n\n    require(tx.outputs[outIdxCredit].assets.lookup(creditAssetIdTxid, creditAssetIdGidx) >= newMintedAmount, \"credit not delivered\");\n\n    require(\n      tx.outputs[outIdxVault].scriptPubKey == new BondMint(\n        borrowerPk, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, newMintedAmount, newCollateral, maturity, auctionWindow, exit\n      ),\n      \"invalid new vault\"\n    );\n    require(tx.outputs[outIdxVault].value >= newCollateral, \"collateral not locked\");\n    require(tx.outputs[outIdxVault].assets.lookup(debitAssetIdTxid, debitAssetIdGidx) >= newMintedAmount, \"debit not custodied in vault\");\n  }\n\n  // LIQUIDATE — pre-maturity MARGIN CALL. Permissionless.\n  function liquidate(pubkey borrowerPk, int vaultIdx, int mintedAmount, int collateral,\n                     int oraclePrice, int oracleTime, signature oracleSig, pubkey auctioneerPk) {\n    require(auctionDiscountBps >= 0, \"negative discount\");\n    require(auctionDiscountBps < 10000, \"discount >= 100%\");\n    require(mintedAmount > 0, \"zero amount\");\n    require(mintedAmount <= totalDebitOutstanding, \"exceeds outstanding\");\n    require(tx.time < maturity, \"matured; use acceptAuction\");\n    require(oraclePrice > 0, \"invalid oracle price\");\n\n    int oracleAge = tx.offchainTime - oracleTime;\n    require(oracleAge >= 0, \"future-dated oracle\");\n    require(oracleAge <= oracleMaxAgeSeconds, \"stale oracle\");\n    let oracleMsg = sha256(ticker + oraclePrice + oracleTime);\n    require(checkSigFromStack(oracleSig, oraclePk, oracleMsg), \"invalid oracle signature\");\n\n    require(\n      tx.inputs[vaultIdx].scriptPubKey == new BondMint(\n        borrowerPk, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, mintedAmount, collateral, maturity, auctionWindow, exit\n      ),\n      \"vault input mismatch\"\n    );\n\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.sumInputs == debitGroup.sumOutputs + mintedAmount, \"debit not burned exactly mintedAmount\");\n    let creditGroup = tx.assetGroups.find(creditAssetIdTxid, creditAssetIdGidx);\n    require(creditGroup.delta == 0, \"credit must not move on liquidation\");\n    let ccGroup = tx.assetGroups.find(creditCtrlIdTxid, creditCtrlIdGidx);\n    require(ccGroup.delta == 0, \"credit control changed\");\n    let dcGroup = tx.assetGroups.find(debitCtrlIdTxid, debitCtrlIdGidx);\n    require(dcGroup.delta == 0, \"debit control changed\");\n\n    int collateralValue = collateral * oraclePrice / 100000000;\n    int healthFloor = mintedAmount * liqThresholdBps / 10000;\n    require(collateralValue < healthFloor, \"vault still healthy\");\n\n    int debitNext = totalDebitOutstanding - mintedAmount;\n    int payRate = 10000 - auctionDiscountBps;\n\n    if (collateralValue >= mintedAmount) {\n      int collateralSold  = mintedAmount * 100000000 / oraclePrice;\n      int excess          = collateral - collateralSold;\n      int liquidationUsdt = mintedAmount * payRate / 10000;\n      int usdtNext        = usdtBalance + liquidationUsdt;\n      require(\n        tx.outputs[0].scriptPubKey == new RepaymentPool(\n          usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n          oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n          usdtNext, totalCreditOutstanding, debitNext, exit\n        ),\n        \"invalid pool recreation\"\n      );\n      require(tx.outputs[0].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtNext, \"liquidation proceeds short\");\n      require(tx.outputs[0].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n      require(tx.outputs[0].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n      require(tx.outputs[1].value >= collateralSold, \"auctioneer underpaid\");\n      require(tx.outputs[1].scriptPubKey == new SingleSig(auctioneerPk, exit), \"output 1 not auctioneer\");\n      if (excess > 330) {\n        require(tx.outputs[2].value >= excess, \"borrower underpaid\");\n        require(tx.outputs[2].scriptPubKey == new SingleSig(borrowerPk, exit), \"output 2 not borrower\");\n      }\n    } else {\n      int liquidationUsdt = collateralValue * payRate / 10000;\n      int usdtNext        = usdtBalance + liquidationUsdt;\n      require(\n        tx.outputs[0].scriptPubKey == new RepaymentPool(\n          usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n          oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n          usdtNext, totalCreditOutstanding, debitNext, exit\n        ),\n        \"invalid pool recreation\"\n      );\n      require(tx.outputs[0].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtNext, \"liquidation proceeds short\");\n      require(tx.outputs[0].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n      require(tx.outputs[0].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n      require(tx.outputs[1].value >= collateral, \"auctioneer underpaid\");\n      require(tx.outputs[1].scriptPubKey == new SingleSig(auctioneerPk, exit), \"output 1 not auctioneer\");\n    }\n  }\n\n  // ACCEPT AUCTION — at/after maturity, in the auction window. Permissionless.\n  function acceptAuction(pubkey borrowerPk, int vaultIdx, int mintedAmount, int collateral,\n                         int oraclePrice, int oracleTime, signature oracleSig, pubkey auctioneerPk) {\n    require(auctionDiscountBps >= 0, \"negative discount\");\n    require(auctionDiscountBps < 10000, \"discount >= 100%\");\n    require(mintedAmount > 0, \"zero amount\");\n    require(mintedAmount <= totalDebitOutstanding, \"exceeds outstanding\");\n    require(tx.time >= maturity, \"not yet matured\");\n    int windowEnd = maturity + auctionWindow;\n    require(tx.time < windowEnd, \"auction window closed\");\n    require(oraclePrice > 0, \"invalid oracle price\");\n\n    int oracleAge = tx.offchainTime - oracleTime;\n    require(oracleAge >= 0, \"future-dated oracle\");\n    require(oracleAge <= oracleMaxAgeSeconds, \"stale oracle\");\n    let oracleMsg = sha256(ticker + oraclePrice + oracleTime);\n    require(checkSigFromStack(oracleSig, oraclePk, oracleMsg), \"invalid oracle signature\");\n\n    require(\n      tx.inputs[vaultIdx].scriptPubKey == new BondMint(\n        borrowerPk, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, mintedAmount, collateral, maturity, auctionWindow, exit\n      ),\n      \"vault input mismatch\"\n    );\n\n    let debitGroup = tx.assetGroups.find(debitAssetIdTxid, debitAssetIdGidx);\n    require(debitGroup.sumInputs == debitGroup.sumOutputs + mintedAmount, \"debit not burned exactly mintedAmount\");\n    let creditGroup = tx.assetGroups.find(creditAssetIdTxid, creditAssetIdGidx);\n    require(creditGroup.delta == 0, \"credit must not move on auction\");\n    let ccGroup = tx.assetGroups.find(creditCtrlIdTxid, creditCtrlIdGidx);\n    require(ccGroup.delta == 0, \"credit control changed\");\n    let dcGroup = tx.assetGroups.find(debitCtrlIdTxid, debitCtrlIdGidx);\n    require(dcGroup.delta == 0, \"debit control changed\");\n\n    int collateralValue = collateral * oraclePrice / 100000000;\n    int debitNext = totalDebitOutstanding - mintedAmount;\n    int payRate = 10000 - auctionDiscountBps;\n\n    if (collateralValue >= mintedAmount) {\n      int collateralSold = mintedAmount * 100000000 / oraclePrice;\n      int excess         = collateral - collateralSold;\n      int auctionUsdt    = mintedAmount * payRate / 10000;\n      int usdtNext       = usdtBalance + auctionUsdt;\n      require(\n        tx.outputs[0].scriptPubKey == new RepaymentPool(\n          usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n          oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n          usdtNext, totalCreditOutstanding, debitNext, exit\n        ),\n        \"invalid pool recreation\"\n      );\n      require(tx.outputs[0].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtNext, \"auction proceeds short\");\n      require(tx.outputs[0].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n      require(tx.outputs[0].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n      require(tx.outputs[1].value >= collateralSold, \"auctioneer underpaid\");\n      require(tx.outputs[1].scriptPubKey == new SingleSig(auctioneerPk, exit), \"output 1 not auctioneer\");\n      if (excess > 330) {\n        require(tx.outputs[2].value >= excess, \"borrower underpaid\");\n        require(tx.outputs[2].scriptPubKey == new SingleSig(borrowerPk, exit), \"output 2 not borrower\");\n      }\n    } else {\n      int auctionUsdt = collateralValue * payRate / 10000;\n      int usdtNext    = usdtBalance + auctionUsdt;\n      require(\n        tx.outputs[0].scriptPubKey == new RepaymentPool(\n          usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n          oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n          usdtNext, totalCreditOutstanding, debitNext, exit\n        ),\n        \"invalid pool recreation\"\n      );\n      require(tx.outputs[0].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtNext, \"auction proceeds short\");\n      require(tx.outputs[0].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n      require(tx.outputs[0].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n      require(tx.outputs[1].value >= collateral, \"auctioneer underpaid\");\n      require(tx.outputs[1].scriptPubKey == new SingleSig(auctioneerPk, exit), \"output 1 not auctioneer\");\n    }\n  }\n\n  // REDEEM — after the auction window closes, credit holders burn credit for\n  // pro-rata USDT. payout = amount * usdtBalance / totalCreditOutstanding.\n  //   output[0]: pool re-created (usdt - payout, totalCredit - amount)\n  //   output[1]: payout USDT → holder (SingleSig — clean single-owner exit)\n  function redeem(int amount, pubkey holderPk, signature holderSig) {\n    require(amount > 0, \"zero redeem\");\n    int redeemStart = maturity + auctionWindow;\n    require(tx.time >= redeemStart, \"auction window not closed\");\n    require(checkSig(holderSig, holderPk), \"invalid holder sig\");\n    require(amount <= totalCreditOutstanding, \"exceeds outstanding\");\n    require(totalCreditOutstanding > 0, \"no credit outstanding\");\n    require(usdtBalance > 0, \"pool empty\");\n\n    int payout = amount * usdtBalance / totalCreditOutstanding;\n    require(payout > 0, \"payout rounds to zero\");\n\n    let creditGroup = tx.assetGroups.find(creditAssetIdTxid, creditAssetIdGidx);\n    require(creditGroup.sumInputs == creditGroup.sumOutputs + amount, \"credit not burned exactly amount\");\n    let ccGroup = tx.assetGroups.find(creditCtrlIdTxid, creditCtrlIdGidx);\n    require(ccGroup.delta == 0, \"credit control changed\");\n    let dcGroup = tx.assetGroups.find(debitCtrlIdTxid, debitCtrlIdGidx);\n    require(dcGroup.delta == 0, \"debit control changed\");\n\n    int usdtNext   = usdtBalance - payout;\n    int creditNext = totalCreditOutstanding - amount;\n\n    require(\n      tx.outputs[0].scriptPubKey == new RepaymentPool(\n        usdtAssetIdTxid, usdtAssetIdGidx, creditAssetIdTxid, creditAssetIdGidx, creditCtrlIdTxid, creditCtrlIdGidx, debitAssetIdTxid, debitAssetIdGidx, debitCtrlIdTxid, debitCtrlIdGidx, ticker,\n        oraclePk, oracleMaxAgeSeconds, initRatioBps, liqThresholdBps, maturity, auctionWindow, auctionDiscountBps,\n        usdtNext, creditNext, totalDebitOutstanding, exit\n      ),\n      \"invalid pool recreation\"\n    );\n    require(tx.outputs[0].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= usdtNext, \"pool usdt short\");\n    require(tx.outputs[0].assets.lookup(creditCtrlIdTxid, creditCtrlIdGidx) >= 1, \"credit control not retained\");\n    require(tx.outputs[0].assets.lookup(debitCtrlIdTxid, debitCtrlIdGidx) >= 1, \"debit control not retained\");\n\n    require(tx.outputs[1].assets.lookup(usdtAssetIdTxid, usdtAssetIdGidx) >= payout, \"holder underpaid\");\n    require(tx.outputs[1].scriptPubKey == new SingleSig(holderPk, exit), \"redeem dest not holder\");\n  }\n}\n";

export const bridge_mint = "// Advanced Bridge — Mint Contract (deposit leg)\n//\n// Brings a foreign-chain asset (ETH, SOL, USDT, ...) onto Arkade as a\n// wrapped asset. A k-of-n custodian quorum observes a confirmed deposit on\n// the source chain and attests it; the covenant then mints exactly the\n// attested amount to the depositor.\n//\n// Flow:\n//   1. The user requests a per-user deposit address for the source chain\n//      from the bridge operator and sends the native asset to it.\n//   2. After the source-chain deposit confirms, each custodian\n//      independently signs, off-line, the attestation message\n//        msg = sha256(depositId || recipientSpk || amount || nonce)\n//      where:\n//        - depositId    domain-separated hash of the source-chain deposit,\n//                       e.g. sha256(\"arkade-bridge-deposit-v1\" || chain\n//                                   || txid || vout);\n//        - recipientSpk the 34-byte Arkade script pubkey the wrapped tokens\n//                       must land on;\n//        - amount       the wrapped amount to mint;\n//        - nonce        this contract's current mint sequence number.\n//   3. Anyone (typically a relayer) collects `threshold` signatures and\n//      spends this UTXO: the covenant mints `amount` wrapped tokens to\n//      recipientSpk and re-creates the bridge state with nonce + 1.\n//\n// Because custodians sign a small fixed message rather than a live\n// transaction, their keys never touch transaction-construction machinery\n// and can stay air-gapped — the attestation is an oracle-style signature,\n// not a spending signature.\n//\n// Replay protection: the attestation binds this contract's `nonce`, and\n// every mint advances it in the continuation output, so a given\n// attestation is single-use.\n//\n// Supply integrity: minting requires the control asset (held by this\n// contract) to be present and preserved, so wrapped supply can only grow\n// through quorum-attested deposits, and only by the exact attested amount.\n//\n// The attestation commits to an arbitrary script pubkey, so a deposit can\n// be minted straight into another contract — e.g. a NonInteractiveSwap\n// offer — letting a cross-chain deposit and an on-chain trade compose in\n// one step.\n\ncontract BridgeMint(\n  // Wrapped asset (e.g. wrapped USDT on Arkade)\n  bytes32 tokenAssetIdTxid,\n  int tokenAssetIdGidx,\n  // Control asset gating mint authority for the wrapped asset\n  bytes32 ctrlAssetIdTxid,\n  int ctrlAssetIdGidx,\n  // Bridge custodian set and quorum threshold (k-of-n)\n  pubkey[] custodians,\n  int threshold,\n  // Mint sequence number; advances by 1 on every mint\n  int nonce,\n  // Exit timelock in blocks (propagated for playground parity)\n  int exit\n) {\n  // Mint: quorum-attested deposit credit.\n  //\n  // Transaction layout:\n  //   input[0]:  this BridgeMint UTXO (carries the control asset)\n  //   output[0]: next BridgeMint state (control asset, nonce + 1)\n  //   output[1]: `amount` wrapped tokens to recipientSpk\n  function mint(\n    int amount,\n    bytes recipientSpk,\n    bytes32 depositId,\n    signature[] custodianSigs\n  ) {\n    require(amount > 0, \"zero mint\");\n    require(threshold > 0, \"zero threshold\");\n    require(size(recipientSpk) == 34, \"bad recipient spk\");\n\n    // Reconstruct the custodian-signed deposit attestation on stack.\n    let attestedMsg = sha256(depositId + recipientSpk + amount + nonce);\n    int valid = 0;\n    for (i, sig) in custodianSigs {\n      if (checkSigFromStack(sig, custodians[i], attestedMsg)) {\n        valid = valid + 1;\n      }\n    }\n    require(valid >= threshold, \"quorum failed\");\n\n    // Supply grows by exactly the attested amount, under the control asset.\n    let tokenGroup = tx.assetGroups.find(tokenAssetIdTxid, tokenAssetIdGidx);\n    require(tokenGroup.delta == amount, \"delta mismatch\");\n    require(tokenGroup.controlIs(ctrlAssetIdTxid, ctrlAssetIdGidx), \"wrong control\");\n\n    let ctrlGroup = tx.assetGroups.find(ctrlAssetIdTxid, ctrlAssetIdGidx);\n    require(ctrlGroup.delta == 0, \"ctrl supply changed\");\n\n    // Recipient receives the minted tokens at the attested script.\n    require(\n      tx.outputs[1].assets.lookup(tokenAssetIdTxid, tokenAssetIdGidx) >= amount,\n      \"mint short\"\n    );\n    require(tx.outputs[1].scriptPubKey == recipientSpk, \"wrong recipient\");\n\n    // State continuation: same bridge, nonce advanced, control retained.\n    int nextNonce = nonce + 1;\n    require(\n      tx.outputs[0].scriptPubKey == new BridgeMint(\n        tokenAssetIdTxid, tokenAssetIdGidx,\n        ctrlAssetIdTxid, ctrlAssetIdGidx,\n        custodians, threshold, nextNonce, exit\n      ),\n      \"state broken\"\n    );\n    require(\n      tx.outputs[0].assets.lookup(ctrlAssetIdTxid, ctrlAssetIdGidx) > 0,\n      \"ctrl not continued\"\n    );\n  }\n}\n";

export const bridge_withdrawal = "// Advanced Bridge — Withdrawal Contract (withdrawal leg)\n//\n// Sends a wrapped asset back to its native chain. The user escrows the\n// wrapped tokens against a destination commitment; the bridge pays out the\n// native asset on the destination chain; a k-of-n custodian quorum attests\n// the payout and burns the escrow. If the bridge never pays out, the user\n// reclaims unilaterally after a timeout — the withdrawal leg carries a\n// consensus-enforced refund, not just an operational promise.\n//\n// Flow:\n//   1. The user locks `amount` wrapped tokens in this escrow, committing to\n//      a destination via destHash (a domain-separated hash of the\n//      destination chain + address, e.g.\n//        sha256(\"arkade-bridge-withdrawal-v1\" || chain || address))\n//      and a unique withdrawalId chosen at escrow creation.\n//   2. The bridge operator reads the destination (revealed off-chain) and\n//      pays out the native asset on the destination chain.\n//   3. Each custodian independently signs, off-line, the attestation\n//        msg = sha256(withdrawalId || destHash || amount)\n//      confirming the payout; release() collects `threshold` signatures and\n//      burns the wrapped tokens, shrinking supply to match the native funds\n//      released on the destination chain.\n//   4. If the bridge never pays out, the user reclaims the wrapped tokens\n//      via refund() after refundTime (block height), bounding custodial\n//      risk to the refund window. Operator policy must stop honoring\n//      payouts before refundTime (the standard HTLC-style safety delta).\n//\n// As on the deposit leg, custodians sign a small fixed attestation rather\n// than a live transaction, so signing keys stay off the transaction path\n// and can remain air-gapped.\n//\n// Replay protection: withdrawalId is unique per escrow, so a release\n// attestation for one escrow cannot release a different one — even for an\n// identical destination and amount.\n\ncontract BridgeWithdrawal(\n  // User who owns the escrowed wrapped tokens\n  pubkey ownerPk,\n  // Wrapped asset being withdrawn\n  bytes32 tokenAssetIdTxid,\n  int tokenAssetIdGidx,\n  // Bridge custodian set and quorum threshold (k-of-n)\n  pubkey[] custodians,\n  int threshold,\n  // Unique withdrawal identifier (salt) chosen at escrow creation\n  bytes32 withdrawalId,\n  // Commitment to the destination chain + address\n  bytes32 destHash,\n  // Amount of wrapped tokens to burn on release\n  int amount,\n  // Block height after which the owner can reclaim\n  int refundTime,\n  // Exit timelock in blocks\n  int exit\n) {\n  // Release: custodian quorum attests the destination-chain payout;\n  // the escrowed wrapped tokens are burned (supply shrinks to match the\n  // native funds released on the destination chain).\n  function release(signature[] custodianSigs) {\n    require(threshold > 0, \"zero threshold\");\n\n    // Reconstruct the custodian-signed payout attestation on stack.\n    let attestedMsg = sha256(withdrawalId + destHash + amount);\n    int valid = 0;\n    for (i, sig) in custodianSigs {\n      if (checkSigFromStack(sig, custodians[i], attestedMsg)) {\n        valid = valid + 1;\n      }\n    }\n    require(valid >= threshold, \"quorum failed\");\n\n    // Burn: at least `amount` wrapped tokens leave circulation.\n    let tokenGroup = tx.assetGroups.find(tokenAssetIdTxid, tokenAssetIdGidx);\n    require(tokenGroup.sumInputs >= tokenGroup.sumOutputs + amount, \"burn short\");\n  }\n\n  // Refund: owner reclaims the wrapped tokens if the bridge never pays out.\n  function refund(signature ownerSig) {\n    require(tx.time >= refundTime, \"refund not reached\");\n    require(checkSig(ownerSig, ownerPk), \"invalid owner sig\");\n  }\n\n  // Unilateral exit (CSV): owner recovers after exit delay.\n  function unilateral(signature ownerSig) tapscript {\n    require(older(exit));\n    require(checkSig(ownerSig, ownerPk));\n  }\n}\n";

export const controlled_mint = "// Controlled Mint Contract\n// Demonstrates asset group introspection primitives\n//\n// This contract manages a token minting authority where:\n// 1. mint() - Authority can mint new tokens (delta > 0), control asset required\n// 2. burn() - Anyone can burn tokens (delta < 0), no control needed\n// 3. lockSupply() - Authority burns the control asset to lock supply forever\n//\n// Asset groups provide aggregate views of asset flows across all inputs/outputs,\n// enabling balance verification without iterating individual UTXOs.\n\nimport \"single_sig.ark\";\n\ncontract ControlledMint(\n  bytes32 tokenAssetIdTxid,\n  int tokenAssetIdGidx,\n  bytes32 ctrlAssetIdTxid,\n  int ctrlAssetIdGidx,\n  pubkey issuerPk,\n  int exit\n) {\n  // Mint: delta > 0, control asset present and retained\n  function mint(int amount, pubkey recipientPk, signature issuerSig) {\n    let tokenGroup = tx.assetGroups.find(tokenAssetIdTxid, tokenAssetIdGidx);\n    require(tokenGroup.delta == amount, \"delta mismatch\");\n    require(tokenGroup.controlIs(ctrlAssetIdTxid, ctrlAssetIdGidx), \"wrong control\");\n\n    let ctrlGroup = tx.assetGroups.find(ctrlAssetIdTxid, ctrlAssetIdGidx);\n    require(ctrlGroup.delta == 0, \"ctrl supply changed\");\n\n    require(tx.outputs[0].assets.lookup(tokenAssetIdTxid, tokenAssetIdGidx) >= amount, \"mint short\");\n    require(tx.outputs[0].scriptPubKey == new SingleSig(recipientPk, exit), \"wrong dest\");\n    require(checkSig(issuerSig, issuerPk), \"bad sig\");\n  }\n\n  // Burn: delta < 0, no control asset needed\n  function burn(int amount, signature ownerSig, pubkey ownerPk) {\n    let tokenGroup = tx.assetGroups.find(tokenAssetIdTxid, tokenAssetIdGidx);\n    require(tokenGroup.sumInputs >= tokenGroup.sumOutputs + amount, \"burn short\");\n    require(checkSig(ownerSig, ownerPk), \"bad sig\");\n  }\n\n  // Lock supply forever: burn the control asset\n  function lockSupply(signature issuerSig) {\n    let ctrlGroup = tx.assetGroups.find(ctrlAssetIdTxid, ctrlAssetIdGidx);\n    require(ctrlGroup.sumOutputs == 0, \"ctrl not burned\");\n    require(checkSig(issuerSig, issuerPk), \"bad sig\");\n  }\n\n  // Unilateral exit (CSV): issuer recovers after exit delay.\n  function unilateral(signature issuerSig) tapscript {\n    require(older(exit));\n    require(checkSig(issuerSig, issuerPk));\n  }\n}\n";

export const fee_adapter = "// Fee Adapter Contract\n// Demonstrates arithmetic expressions with tx input/output verification\n//\n// This contract implements a fee-taking adapter where:\n// 1. execute() - Processes a payment, verifying output asset balances\n// 2. The output must preserve assets minus fee\n//\n// Uses asset lookups on tx.inputs and tx.outputs with arithmetic\n// comparisons for balance verification.\n\ncontract FeeAdapter(\n  pubkey senderPk,\n  pubkey operatorPk,\n  pubkey recipientPk,\n  bytes32 paymentAssetIdTxid,\n  int paymentAssetIdGidx,\n  int minFee,\n  int exit\n) {\n  // Execute: process payment with fee deduction\n  // Verifies that the output asset balance reflects the fee deduction\n  function execute(signature senderSig, int fee) {\n    // Fee must be at least the minimum\n    require(fee >= minFee, \"fee below minimum\");\n\n    // Input must contain the payment asset\n    require(tx.inputs[0].assets.lookup(paymentAssetIdTxid, paymentAssetIdGidx) > 0, \"no payment asset in input\");\n\n    // Output must contain the payment asset (minus fee)\n    require(tx.outputs[0].assets.lookup(paymentAssetIdTxid, paymentAssetIdGidx) > 0, \"no payment asset in output\");\n\n    // Sender must sign\n    require(checkSig(senderSig, senderPk), \"invalid sender signature\");\n  }\n\n  // Adjust: operator adjusts fee parameters\n  function adjust(signature operatorSig) {\n    // Operator must sign\n    require(checkSig(operatorSig, operatorPk), \"invalid operator signature\");\n  }\n\n  // Unilateral exit (CSV): sender recovers after exit delay.\n  function unilateral(signature senderSig) tapscript {\n    require(older(exit));\n    require(checkSig(senderSig, senderPk));\n  }\n}\n";

export const fuji_safe = "// Fuji Safe Contract\ncontract FujiSafe(\n  // The asset commitment hash (client-side validated)\n  bytes assetCommitmentHash,\n  // The amount being borrowed\n  int borrowAmount,\n  // The borrower's public key\n  pubkey borrowerPk,\n  // The treasury's public key\n  pubkey treasuryPk,\n  // The expiration timeout in blocks\n  int expirationTimeout,\n  // The price level for liquidation\n  int priceLevel,\n  // The setup timestamp\n  int setupTimestamp,\n  // The oracle's public key\n  pubkey oraclePk,\n  // The asset pair identifier\n  bytes assetPair,\n  // Exit timelock in blocks\n  int exit\n) {\n  // Helper function to verify Fuji token burning via Taproot output\n  // Takes the pubkey to use as the internal key for the P2TR output\n  function verifyFujiBurning(pubkey internalKey) internal {\n    // In Taproot, we verify the output is a P2TR that commits to our asset\n    // Using the provided pubkey as the internal key\n    bytes p2trScript = new P2TR(internalKey, assetCommitmentHash);\n\n    // Verify output 0 has the correct P2TR scriptPubKey and value\n    require(tx.outputs[0].scriptPubKey == p2trScript, \"P2TR output mismatch\");\n    require(tx.outputs[0].value == borrowAmount, \"Value mismatch\");\n  }\n\n  // Claim: Treasury can unlock all collateral after expiration when burning Fuji\n  function claim(signature treasurySig) {\n    // Check that expiration timeout has passed\n    require(tx.time >= expirationTimeout, \"Expiration timeout not reached\");\n\n    // Verify burning of Fuji token using treasury key\n    verifyFujiBurning(treasuryPk);\n\n    // Require treasury signature\n    require(checkSig(treasurySig, treasuryPk), \"Invalid treasury signature\");\n  }\n\n  // Liquidation: Treasury can unlock all collateral with attestation price below the liquidation target\n  function liquidate(int currentPrice, signature oracleSig, signature treasurySig) {\n    // Check price is below liquidation threshold\n    require(currentPrice < priceLevel, \"Price not below liquidation threshold\");\n\n    // Verify timestamp is after setup\n    require(tx.time >= setupTimestamp, \"Timestamp before setup\");\n\n    // Create message for oracle signature verification\n    bytes message = sha256(assetPair);\n\n    // Verify oracle signature on price data\n    require(checkSigFromStack(oracleSig, oraclePk, message), \"Invalid oracle signature\");\n\n    // Verify burning of Fuji token using treasury key\n    verifyFujiBurning(treasuryPk);\n\n    // Require treasury signature\n    require(checkSig(treasurySig, treasuryPk), \"Invalid treasury signature\");\n  }\n\n  // Private Redemption: Only owner can unlock all collateral with key when burning Fuji\n  function redeem(signature borrowerSig) {\n    // Verify burning of Fuji token using borrower key\n    verifyFujiBurning(borrowerPk);\n\n    // Require borrower signature\n    require(checkSig(borrowerSig, borrowerPk), \"Invalid borrower signature\");\n  }\n\n  // Treasury Renew: Treasury can unilaterally renew the expiration time\n  function renew(signature treasurySig) {\n    int currentValue = tx.input.current.value;\n\n    // Recreate same contract with identical parameters\n    require(\n      tx.outputs[0].scriptPubKey == new FujiSafe(\n        assetCommitmentHash, borrowAmount, borrowerPk, treasuryPk,\n        expirationTimeout, priceLevel, setupTimestamp, oraclePk, assetPair, exit\n      ),\n      \"contract mismatch\"\n    );\n    require(tx.outputs[0].value == currentValue, \"Value mismatch\");\n\n    // Require treasury signature\n    require(checkSig(treasurySig, treasuryPk), \"Invalid treasury signature\");\n  }\n\n  // Unilateral exit (CSV): borrower recovers after exit delay.\n  function unilateral(signature borrowerSig) tapscript {\n    require(older(exit));\n    require(checkSig(borrowerSig, borrowerPk));\n  }\n}\n";

export const htlc = "contract HTLC(\n  pubkey sender,\n  pubkey receiver,\n  bytes20 preimageHash,\n  int refundTime,\n  int exit\n) {\n  // Covenants (emulator): pin the payout to the right party for >= input value.\n  function claim() {\n    require(tx.outputs[0].value >= tx.inputs[0].value);\n  }\n  function refund() {\n    require(tx.outputs[0].value >= tx.inputs[0].value);\n  }\n\n  // L1 leaves, bound by name.\n  function claim(bytes preimage, signature serverSig, signature emulatorSig) tapscript {\n    require(hash160(preimage) == preimageHash);\n    require(checkMultisig([server, emulator], [serverSig, emulatorSig], 2));\n  }\n  function refund(signature serverSig, signature emulatorSig) tapscript {\n    require(tx.time >= refundTime);\n    require(checkMultisig([server, emulator], [serverSig, emulatorSig], 2));\n  }\n\n  // Unilateral exit (CSV).\n  function unilateral(signature senderSig) tapscript {\n    require(older(exit));\n    require(checkSig(senderSig, sender));\n  }\n}\n";

export const endpoint = "// Endpoint Contract — LayerZero / USDT0 pathway state\n//\n// Spec: layerzero-usdt0-arkade-demo/internal/scripts/builders.go\n//       BuildEndpointReceiveScript + BuildEndpointSendScript.\n//\n// The Endpoint owns LayerZero pathway state: local Endpoint identity, linked\n// OApp identity, remote endpoint id, remote OApp id, DVN set, inbound/outbound\n// nonces, and the two invocation marker mints/burns. This file now expresses\n// the full Go-script semantics natively using introspector primitives:\n//\n//   tx.packet(PacketType)          — current-tx extension packet\n//   substr / cat / bin2num         — fixed-width field extraction\n//   sha256(substr(...))            — DVN attestation hash binding\n//   checkSigFromStack              — DVN Schnorr verification\n//   tx.outputs[0].scriptPubKey ==  — recursive covenant (state continuation)\n//     tx.input.current.scriptPubKey\n//   tx.outputs[1].scriptPubKey ==  — canonical pkScript pinning\n//     new ReceiveMarker(...)        for marker outputs\n//\n// Packet type ids (16 = EndpointState 0x10, 17 = LzReceive 0x11,\n// 18 = DvnAttestation 0x12, 19 = LzSend 0x13, 20 = OAppSendInvocation 0x14)\n// appear as integer literals below; once the language gains compile-time\n// constants (`const int ENDPOINT_STATE_PACKET_ID = 16;` …) these should be\n// hoisted to named declarations.\n//\n// Packet layout constants (from internal/scripts/builders.go offsets):\n//\n//   EndpointStatePacket (size 183, type 0x10):\n//     1..1   version (0x01)\n//     1..33  endpointID (32)\n//     33..65 oappID (32)\n//     65..69 remoteEID (4, BE)\n//     69..101 remoteOApp (32)\n//     101..102 dvnThreshold\n//     102..103 dvnCount\n//     103..135 dvn0 pk\n//     135..167 dvn1 pk\n//     167..175 inboundNonce (u64 BE)\n//     175..183 outboundNonce (u64 BE)\n//\n//   LzReceivePacket (size 219 with credit body, type 0x11):\n//     0..1   version\n//     1..33  receiver (= oappID)\n//     33..37 srcEID\n//     37..69 sender (= remoteOApp)\n//     69..77 nonce\n//     77..109 GUID\n//     109..141 messageHash\n//     141..145 messageLen (u32 BE) = 74\n//     145..219 CreditMessage (74 bytes)\n//\n//   DvnAttestationPacket (size 228, type 0x12):\n//     0..1   version\n//     1..33  attestedHash\n//     33..34 attestationCount (= 2)\n//     34..35 att0 index (= 0)\n//     35..67 att0 pubkey\n//     67..131 att0 signature (64)\n//     131..132 att1 index (= 1)\n//     132..164 att1 pubkey\n//     164..228 att1 signature (64)\n//\n//   OAppSendInvocationPacket (size 175, type 0x14):\n//     0..1   version\n//     1..33  oappID\n//     33..65 endpointID\n//     65..67 invocation_vout (u16 BE)\n//     67..71 dstEID\n//     71..103 receiver\n//     103..111 amountSD\n//     111..143 remoteRecipient\n//     143..175 messageHash\n//\n//   LzSendPacket (size 181, type 0x13):\n//     0..1   version\n//     1..33  sender (= oappID)\n//     33..37 dstEID\n//     37..69 receiver (= remoteOApp)\n//     69..77 nonce\n//     77..109 GUID = sha256(OAppSendInvocation)\n//     109..117 amountSD\n//     117..149 remoteRecipient\n//     149..181 messageHash\n\ncontract Endpoint(\n  bytes32 endpointCtrlAssetIdTxid,\n  int     endpointCtrlAssetIdGidx,\n  bytes32 endpointIDAssetIdTxid,\n  int     endpointIDAssetIdGidx,\n  bytes32 oappCtrlAssetIdTxid,\n  int     oappCtrlAssetIdGidx,\n  bytes32 oappIDAssetIdTxid,\n  int     oappIDAssetIdGidx,\n  bytes32 endpointID,\n  bytes32 oappID,\n  int     remoteEID,\n  bytes32 remoteOApp,\n  pubkey  dvn0Pk,\n  pubkey  dvn1Pk\n) {\n\n  // -------------------------------------------------------------------------\n  // ENDPOINT RECEIVE\n  // Validate a DVN-attested LzReceive packet and emit a receive-invocation\n  // marker for OApp.receive() to consume.\n  //\n  // Witness inputs (prover-supplied; the introspector layer binds them to\n  // the canonical packet-derived values via the on-chain checks below):\n  //   - attestedHash : sha256(LzReceive[1..141]) — receive header digest.\n  //     Pinned twice on chain: against sha256(substr(packet17, 1, 140)) and\n  //     against substr(packet18, 1, 32). Both DVN sigs verify over it.\n  //   - dvn0Sig / dvn1Sig : Schnorr signatures from the two configured DVNs.\n  //\n  // On-chain enforcement (mirrors BuildEndpointReceiveScript end-to-end):\n  //   - Packets EndpointState/LzReceive/DvnAttestation are v1 with fixed size.\n  //   - Route fields (endpointID, oappID, remoteEID, remoteOApp) match config.\n  //   - DVN threshold/count are both 2.\n  //   - In-packet DVN pubkeys match the contract-baked DVN keys.\n  //   - DVN 0 + DVN 1 Schnorr signatures verify against the attestedHash.\n  //   - attestedHash equals sha256(LzReceive[1..141]) (receive header bytes).\n  //   - Endpoint control asset survives on output[0] (next Endpoint state).\n  //   - One EndpointID asset is minted on output[1] (receive marker).\n  //   - Output[1] uses the canonical ReceiveMarker pkScript.\n  // -------------------------------------------------------------------------\n  function receive(\n    bytes32 receiveMarkerScriptHash,\n    bytes32 attestedHash,\n    signature dvn0Sig,\n    signature dvn1Sig\n  ) {\n    // Pull the three current-tx packets. tx.packet() asserts presence.\n    require(size(tx.packet(16)) == 183, \"endpoint state packet size\");\n    require(size(tx.packet(17)) == 219, \"lz receive packet size\");\n    require(size(tx.packet(18)) == 228, \"dvn attestation packet size\");\n\n    // Packet versions.\n    require(substr(tx.packet(16), 0, 1) == 1, \"endpoint state version\");\n    require(substr(tx.packet(17), 0, 1) == 1, \"lz receive version\");\n    require(substr(tx.packet(18), 0, 1) == 1, \"dvn attestation version\");\n\n    // Endpoint state route fields are fixed by this contract's configuration.\n    require(substr(tx.packet(16), 1, 32)  == endpointID, \"wrong endpointID\");\n    require(substr(tx.packet(16), 33, 32) == oappID, \"wrong oappID\");\n    require(bin2num(substr(tx.packet(16), 65, 4)) == remoteEID, \"wrong remoteEID\");\n    require(substr(tx.packet(16), 69, 32) == remoteOApp, \"wrong remoteOApp\");\n\n    // DVN threshold and count both equal 2.\n    require(bin2num(substr(tx.packet(16), 101, 1)) == 2, \"dvn threshold != 2\");\n    require(bin2num(substr(tx.packet(16), 102, 1)) == 2, \"dvn count != 2\");\n    require(substr(tx.packet(16), 103, 32) == dvn0Pk, \"endpoint state dvn0 mismatch\");\n    require(substr(tx.packet(16), 135, 32) == dvn1Pk, \"endpoint state dvn1 mismatch\");\n\n    // The LzReceive route fields match Endpoint state.\n    require(substr(tx.packet(17), 1, 32)  == oappID, \"lz receiver != oapp\");\n    require(bin2num(substr(tx.packet(17), 33, 4)) == remoteEID, \"lz srcEID != remote\");\n    require(substr(tx.packet(17), 37, 32) == remoteOApp, \"lz sender != remoteOApp\");\n\n    // DvnAttestation: canonical two-entry layout, attested hash equals the\n    // sha256 of the LzReceive header (receiver..messageHash).\n    require(bin2num(substr(tx.packet(18), 33, 1)) == 2, \"dvn count != 2\");\n    require(bin2num(substr(tx.packet(18), 34, 1)) == 0, \"dvn att0 index != 0\");\n    require(bin2num(substr(tx.packet(18), 131, 1)) == 1, \"dvn att1 index != 1\");\n    require(substr(tx.packet(18), 35, 32) == dvn0Pk, \"dvn att0 pk mismatch\");\n    require(substr(tx.packet(18), 132, 32) == dvn1Pk, \"dvn att1 pk mismatch\");\n    require(\n      sha256(substr(tx.packet(17), 1, 140)) == attestedHash,\n      \"attested hash does not match lz receive header\"\n    );\n    require(substr(tx.packet(18), 1, 32) == attestedHash, \"dvn attested hash mismatch\");\n\n    // DVN 2-of-2 signatures over the attestedHash.\n    require(checkSigFromStack(dvn0Sig, dvn0Pk, attestedHash), \"dvn0 sig invalid\");\n    require(checkSigFromStack(dvn1Sig, dvn1Pk, attestedHash), \"dvn1 sig invalid\");\n\n    // The embedded CreditMessage hashes to LzReceive.messageHash, locking the\n    // marker to the body OApp.receive() will read.\n    require(\n      sha256(substr(tx.packet(17), 145, 74)) == substr(tx.packet(17), 109, 32),\n      \"credit message hash mismatch\"\n    );\n\n    // Endpoint state continuation: output[0] reuses the spent input's\n    // pkScript verbatim (recursive covenant) and carries the Endpoint\n    // control asset. This matches the Go reference exactly:\n    // OP_INSPECTOUTPUTSCRIPTPUBKEY == OP_PUSHCURRENTINPUTINDEX\n    // OP_INSPECTINPUTSCRIPTPUBKEY (BuildEndpointReceiveScript).\n    require(\n      tx.outputs[0].scriptPubKey == tx.input.current.scriptPubKey,\n      \"endpoint state must continue\"\n    );\n    require(\n      tx.outputs[0].assets.lookup(endpointCtrlAssetIdTxid, endpointCtrlAssetIdGidx) == 1,\n      \"endpoint control missing on next state\"\n    );\n\n    // Receive-invocation marker is minted at output[1] with the canonical\n    // ReceiveMarker pkScript. The marker pins itself to the OApp.receive()\n    // closure via its constructor parameter `oappReceiveScriptHash` (passed\n    // here as a function input — the deployment runtime computes it from\n    // the OApp contract definition).\n    require(\n      tx.outputs[1].assets.lookup(endpointIDAssetIdTxid, endpointIDAssetIdGidx) == 1,\n      \"marker asset missing\"\n    );\n    require(\n      tx.outputs[1].scriptPubKey == new ReceiveMarker(\n        receiveMarkerScriptHash, oappCtrlAssetIdTxid, oappCtrlAssetIdGidx\n      ),\n      \"marker pkScript not canonical\"\n    );\n\n    // Exactly one EndpointID asset minted (no extras).\n    let endpointIDGroup = tx.assetGroups.find(endpointIDAssetIdTxid, endpointIDAssetIdGidx);\n    require(endpointIDGroup.sumOutputs == 1, \"extra marker minted\");\n  }\n\n  // -------------------------------------------------------------------------\n  // ENDPOINT SEND\n  // Consume the OApp-emitted send-invocation marker and emit an outbound\n  // LzSendPacket. Endpoint state continues; the OAppID marker is fully burned.\n  // -------------------------------------------------------------------------\n  function send() {\n    require(size(tx.packet(16)) == 183, \"endpoint state packet size\");\n    require(size(tx.packet(19)) == 181, \"lz send packet size\");\n    require(size(tx.inputs[1].packet(20)) == 175, \"send invocation packet size\");\n\n    require(substr(tx.packet(16), 0, 1) == 1, \"endpoint state version\");\n    require(substr(tx.packet(19), 0, 1) == 1, \"lz send version\");\n    require(substr(tx.inputs[1].packet(20), 0, 1) == 1, \"send invocation version\");\n\n    // Route preservation.\n    require(substr(tx.packet(16), 1, 32)  == endpointID, \"wrong endpointID\");\n    require(substr(tx.packet(16), 33, 32) == oappID, \"wrong oappID\");\n    require(bin2num(substr(tx.packet(16), 65, 4)) == remoteEID, \"wrong remoteEID\");\n    require(substr(tx.packet(16), 69, 32) == remoteOApp, \"wrong remoteOApp\");\n\n    // LzSend route fields match Endpoint state.\n    require(substr(tx.packet(19), 1, 32)  == oappID, \"lz send sender != oapp\");\n    require(bin2num(substr(tx.packet(19), 33, 4)) == remoteEID, \"lz dstEID != remote\");\n    require(substr(tx.packet(19), 37, 32) == remoteOApp, \"lz receiver != remoteOApp\");\n\n    // The OApp invocation packet addresses this exact Endpoint/OApp pair.\n    require(substr(tx.inputs[1].packet(20), 1, 32)  == oappID, \"invocation oappID mismatch\");\n    require(substr(tx.inputs[1].packet(20), 33, 32) == endpointID, \"invocation endpointID mismatch\");\n    require(bin2num(substr(tx.inputs[1].packet(20), 67, 4)) == remoteEID, \"invocation dstEID mismatch\");\n    require(substr(tx.inputs[1].packet(20), 71, 32) == remoteOApp, \"invocation receiver mismatch\");\n\n    // LzSend GUID = sha256(OAppSendInvocation) — binds the outbound packet\n    // to the exact invocation body.\n    require(\n      sha256(substr(tx.inputs[1].packet(20), 0, 175)) == substr(tx.packet(19), 77, 32),\n      \"lz send guid mismatch\"\n    );\n\n    // Per-field equalities between invocation and LzSend.\n    require(\n      substr(tx.inputs[1].packet(20), 1, 32) == substr(tx.packet(19), 1, 32),\n      \"invocation/lzSend sender mismatch\"\n    );\n    require(\n      substr(tx.inputs[1].packet(20), 67, 4) == substr(tx.packet(19), 33, 4),\n      \"invocation/lzSend dstEID mismatch\"\n    );\n    require(\n      substr(tx.inputs[1].packet(20), 71, 32) == substr(tx.packet(19), 37, 32),\n      \"invocation/lzSend receiver mismatch\"\n    );\n    require(\n      substr(tx.inputs[1].packet(20), 103, 8) == substr(tx.packet(19), 109, 8),\n      \"invocation/lzSend amount mismatch\"\n    );\n    require(\n      substr(tx.inputs[1].packet(20), 111, 32) == substr(tx.packet(19), 117, 32),\n      \"invocation/lzSend remoteRecipient mismatch\"\n    );\n    require(\n      substr(tx.inputs[1].packet(20), 143, 32) == substr(tx.packet(19), 149, 32),\n      \"invocation/lzSend messageHash mismatch\"\n    );\n\n    // OAppID marker fully burned.\n    let oappIDGroup = tx.assetGroups.find(oappIDAssetIdTxid, oappIDAssetIdGidx);\n    require(oappIDGroup.sumInputs == 1, \"send marker missing\");\n    require(oappIDGroup.sumOutputs == 0, \"send marker not burned\");\n\n    // Endpoint state continues: recursive covenant via the spent input's\n    // own pkScript (see receive() for rationale).\n    require(\n      tx.outputs[0].scriptPubKey == tx.input.current.scriptPubKey,\n      \"endpoint state must continue\"\n    );\n    require(\n      tx.outputs[0].assets.lookup(endpointCtrlAssetIdTxid, endpointCtrlAssetIdGidx) == 1,\n      \"endpoint control missing on next state\"\n    );\n  }\n}\n";

export const oapp = "// OApp Contract — USDT0 mint / burn application\n//\n// Spec: layerzero-usdt0-arkade-demo/internal/scripts/builders.go\n//       BuildOAppReceiveScript + BuildOAppSendScript.\n//\n// The OApp owns the application-level token effects. It mints USDT0 from\n// Endpoint-authenticated receive invocations and burns USDT0 to create\n// authenticated send invocations back to the Endpoint.\n//\n// Packet layout reminders (see endpoint.ark for the full schema):\n//\n//   LzReceivePacket (size 219, type 0x11, presented via input 0):\n//     1..33     receiver (= oappID)\n//     33..37    srcEID (= remoteEID)\n//     37..69    sender (= remoteOApp)\n//     109..141  messageHash\n//     141..145  messageLen (u32 BE) = 74\n//     145..219  CreditMessage (74 bytes):\n//       0..2    P2TR script-pubkey tag (0x5120)\n//       2..34   recipient x-only key\n//       34..42  amount (u64 BE)\n//       42..74  remoteSender\n//\n//   OAppSendInvocationPacket (size 175, type 0x14, produced in current tx):\n//     1..33     oappID\n//     33..65    endpointID\n//     65..67    invocation_vout (u16 BE)\n//     67..71    dstEID\n//     71..103   receiver (= remoteOApp)\n//     103..111  amountSD (u64 BE)\n//     111..143  remoteRecipient\n//     143..175  messageHash\n\ncontract OApp(\n  bytes32 oappCtrlAssetIdTxid,\n  int     oappCtrlAssetIdGidx,\n  bytes32 oappIDAssetIdTxid,\n  int     oappIDAssetIdGidx,\n  bytes32 usdt0AssetIdTxid,\n  int     usdt0AssetIdGidx,\n  bytes32 endpointCtrlAssetIdTxid,\n  int     endpointCtrlAssetIdGidx,\n  bytes32 endpointIDAssetIdTxid,\n  int     endpointIDAssetIdGidx,\n  bytes32 endpointID,\n  bytes32 oappID,\n  int     remoteEID,\n  bytes32 remoteOApp\n) {\n\n  // -------------------------------------------------------------------------\n  // OAPP RECEIVE\n  // Consume a receive-invocation marker (input 0) and mint the credited USDT0\n  // amount to the recipient committed by the inbound CreditMessage.\n  //\n  // The marker carries the LzReceivePacket as an extension packet of the\n  // *previous* Arkade tx (the Endpoint receive); we access it through\n  // tx.inputs[0].packet(LzReceive).\n  // -------------------------------------------------------------------------\n  function receive() {\n    // The previous-tx LzReceive packet on the marker input must be v1 with\n    // the credit-message shape (size 219).\n    require(size(tx.inputs[0].packet(17)) == 219, \"lz receive packet size\");\n    require(substr(tx.inputs[0].packet(17), 0, 1) == 1, \"lz receive version\");\n\n    // CreditMessage length field must equal 74 (creditMessageSize).\n    require(\n      bin2num(substr(tx.inputs[0].packet(17), 141, 4)) == 74,\n      \"credit message length\"\n    );\n\n    // The receive-invocation marker (1 EndpointID asset) is consumed on\n    // input 0 and fully burned.\n    require(\n      tx.inputs[0].assets.lookup(endpointIDAssetIdTxid, endpointIDAssetIdGidx) == 1,\n      \"marker asset not on input 0\"\n    );\n    let endpointIDGroup = tx.assetGroups.find(endpointIDAssetIdTxid, endpointIDAssetIdGidx);\n    require(endpointIDGroup.sumOutputs == 0, \"marker not burned\");\n\n    // LzReceive route fields are pinned by the contract configuration.\n    require(\n      substr(tx.inputs[0].packet(17), 1, 32) == oappID,\n      \"lz receiver != oappID\"\n    );\n    require(\n      bin2num(substr(tx.inputs[0].packet(17), 33, 4)) == remoteEID,\n      \"lz srcEID != remoteEID\"\n    );\n    require(\n      substr(tx.inputs[0].packet(17), 37, 32) == remoteOApp,\n      \"lz sender != remoteOApp\"\n    );\n\n    // The embedded CreditMessage hashes to LzReceive.messageHash. This pins\n    // the body bytes that the Endpoint receive already DVN-attested.\n    require(\n      sha256(substr(tx.inputs[0].packet(17), 145, 74))\n        == substr(tx.inputs[0].packet(17), 109, 32),\n      \"credit message hash mismatch\"\n    );\n\n    // CreditMessage.remoteSender == LzReceive.sender.\n    require(\n      substr(tx.inputs[0].packet(17), 187, 32) == substr(tx.inputs[0].packet(17), 37, 32),\n      \"credit remoteSender mismatch\"\n    );\n\n    // Recipient output's scriptPubKey matches the CreditMessage's full 34-byte\n    // P2TR scriptPubKey field (0x5120 tag prefix + 32-byte x-only key, starting\n    // at LzReceive offset 145).\n    //\n    // OP_INSPECTOUTPUTSCRIPTPUBKEY returns the full scriptPubKey bytes as a\n    // single stack item (see docs/arkade-primitives-spec.md Phase 7 — the\n    // canonical Arkade convention is one-item `outScript(bytes)`, not the\n    // (program, version) two-item form some Liquid-style references describe).\n    // So both sides of this equality are 34 bytes.\n    require(\n      tx.outputs[1].scriptPubKey == substr(tx.inputs[0].packet(17), 145, 34),\n      \"recipient pkScript mismatch\"\n    );\n\n    // Recipient output receives exactly CreditMessage.amount USDT0.\n    require(\n      tx.outputs[1].assets.lookup(usdt0AssetIdTxid, usdt0AssetIdGidx)\n        == bin2num(substr(tx.inputs[0].packet(17), 179, 8)),\n      \"recipient amount mismatch\"\n    );\n\n    // USDT0 delta equals the credited amount.\n    let usdt0Group = tx.assetGroups.find(usdt0AssetIdTxid, usdt0AssetIdGidx);\n    require(\n      usdt0Group.delta == bin2num(substr(tx.inputs[0].packet(17), 179, 8)),\n      \"usdt0 delta != credit amount\"\n    );\n\n    // OApp state continues at output 0 with control + ID assets intact.\n    // Recursive covenant: the output reuses the spent input's pkScript,\n    // matching the Go reference (BuildOAppReceiveScript's\n    // OP_INSPECTOUTPUTSCRIPTPUBKEY == OP_PUSHCURRENTINPUTINDEX\n    // OP_INSPECTINPUTSCRIPTPUBKEY check).\n    require(\n      tx.outputs[0].scriptPubKey == tx.input.current.scriptPubKey,\n      \"oapp state must continue\"\n    );\n    require(tx.outputs[0].assets.lookup(oappCtrlAssetIdTxid, oappCtrlAssetIdGidx) == 1, \"oapp control missing\");\n    require(tx.outputs[0].assets.lookup(oappIDAssetIdTxid, oappIDAssetIdGidx) == 1, \"oapp id missing\");\n  }\n\n  // -------------------------------------------------------------------------\n  // OAPP SEND\n  // Burn the outbound USDT0 amount and emit an OAppSendInvocation packet\n  // alongside a send-invocation marker for Endpoint.send() to consume.\n  //\n  // Authorisation: this function takes no signatures. Mirroring the Go\n  // reference (BuildOAppSendScript), authority comes from\n  //   (a) the OApp control singleton, which only sits on the real OApp state;\n  //   (b) the USDT0 input UTXOs, each requiring their own owner sig under\n  //       their per-UTXO scripts;\n  //   (c) the Arkade server + emulator cosign on the synthesized default\n  //       collaborative tapleaf. No contract-level owner signature exists or\n  //       is needed.\n  // -------------------------------------------------------------------------\n  function send(bytes32 sendMarkerScriptHash) {\n    // Current-tx OAppSendInvocation packet: v1, fixed size.\n    require(size(tx.packet(20)) == 175, \"send invocation packet size\");\n    require(substr(tx.packet(20), 0, 1) == 1, \"send invocation version\");\n\n    // Packet identifies this exact OApp / Endpoint pair.\n    require(substr(tx.packet(20), 1, 32) == oappID, \"invocation oappID\");\n    require(substr(tx.packet(20), 33, 32) == endpointID, \"invocation endpointID\");\n\n    // Destination route matches the configured remote.\n    require(bin2num(substr(tx.packet(20), 67, 4)) == remoteEID, \"invocation dstEID\");\n    require(substr(tx.packet(20), 71, 32) == remoteOApp, \"invocation receiver\");\n\n    // invocation_vout points at the marker output (output 1).\n    require(bin2num(substr(tx.packet(20), 65, 2)) == 1, \"invocation_vout != 1\");\n\n    // USDT0 input sum minus output sum equals the invocation amount\n    // (i.e. delta == -amount). Expressed as monotonic equality on sumInputs\n    // - sumOutputs using the existing group_property arithmetic.\n    let usdt0Group = tx.assetGroups.find(usdt0AssetIdTxid, usdt0AssetIdGidx);\n    require(\n      usdt0Group.sumInputs == usdt0Group.sumOutputs + bin2num(substr(tx.packet(20), 103, 8)),\n      \"burn amount mismatch\"\n    );\n\n    // Send-invocation marker emitted at output 1.\n    require(\n      tx.outputs[1].assets.lookup(oappIDAssetIdTxid, oappIDAssetIdGidx) == 1,\n      \"send marker asset missing\"\n    );\n    require(\n      tx.outputs[1].scriptPubKey == new SendMarker(\n        sendMarkerScriptHash, endpointCtrlAssetIdTxid, endpointCtrlAssetIdGidx\n      ),\n      \"send marker pkScript not canonical\"\n    );\n    let oappIDGroup = tx.assetGroups.find(oappIDAssetIdTxid, oappIDAssetIdGidx);\n    require(oappIDGroup.sumOutputs == 1, \"extra send marker minted\");\n\n    // OApp state continues at output 0: recursive covenant via the spent\n    // input's own pkScript (see receive() for rationale).\n    require(\n      tx.outputs[0].scriptPubKey == tx.input.current.scriptPubKey,\n      \"oapp state must continue\"\n    );\n    require(tx.outputs[0].assets.lookup(oappCtrlAssetIdTxid, oappCtrlAssetIdGidx) == 1, \"oapp control missing\");\n  }\n}\n";

export const receive_marker = "// ReceiveMarker — receive-invocation marker output\n//\n// Spec: layerzero-usdt0-arkade-demo/internal/scripts/builders.go\n//       BuildReceiveInvocationScript.\n//\n// Locks a one-unit EndpointID asset alongside the LzReceivePacket extension\n// data emitted by Endpoint.receive(). Consumable only when the consuming\n// transaction also spends the canonical OApp state UTXO running OApp.receive().\n//\n// Mirrors the three Go-script checks:\n//   1. Marker spent from input position config.ReceiveInvocationInputIndex.\n//   2. The OApp state input was spent through the OApp.receive() Arkade\n//      closure (OP_INSPECTINPUTARKADESCRIPTHASH).\n//   3. Defense-in-depth: OApp control singleton on the OApp state input.\n\ncontract ReceiveMarker(\n  bytes32 oappReceiveScriptHash,\n  bytes32 oappCtrlAssetIdTxid,\n  int     oappCtrlAssetIdGidx\n) {\n  // Single execution path: consumed inside OApp.receive().\n  //\n  // OApp.receive() reads its marker input from input 0 and its OApp state\n  // input from input 1. The marker must be at input 0 (PUSHCURRENTINPUTINDEX),\n  // and input 1 must have been spent through the OApp.receive() Arkade\n  // closure with the OApp control singleton attached.\n  function consume() {\n    // (1) the marker is at the expected input position.\n    require(this.activeInputIndex == 0, \"marker input position\");\n\n    // (2) the OApp state input was spent through the OApp.receive() closure.\n    require(\n      tx.inputs[1].arkadeScriptHash == oappReceiveScriptHash,\n      \"oapp state not via receive closure\"\n    );\n\n    // (3) defense-in-depth: OApp control singleton on the consuming input.\n    require(\n      tx.inputs[1].assets.lookup(oappCtrlAssetIdTxid, oappCtrlAssetIdGidx) == 1,\n      \"oapp state input missing control asset\"\n    );\n  }\n}\n";

export const send_marker = "// SendMarker — send-invocation marker output\n//\n// Spec: layerzero-usdt0-arkade-demo/internal/scripts/builders.go\n//       BuildSendInvocationScript.\n//\n// Locks a one-unit OAppID asset alongside the OAppSendInvocation extension\n// data emitted by OApp.send(). Consumable only when the consuming\n// transaction also spends the canonical Endpoint state UTXO running\n// Endpoint.send(). Symmetric to ReceiveMarker.\n//\n// Mirrors the three Go-script checks:\n//   1. Marker spent from input position config.SendInvocationInputIndex.\n//   2. The Endpoint state input was spent through the Endpoint.send()\n//      Arkade closure (OP_INSPECTINPUTARKADESCRIPTHASH).\n//   3. Defense-in-depth: Endpoint control singleton on the Endpoint state input.\n\ncontract SendMarker(\n  bytes32 endpointSendScriptHash,\n  bytes32 endpointCtrlAssetIdTxid,\n  int     endpointCtrlAssetIdGidx\n) {\n  // Single execution path: consumed inside Endpoint.send().\n  //\n  // Endpoint.send() reads its Endpoint state input from input 0 and the\n  // OApp-emitted send marker from input 1. The marker must be at input 1\n  // (PUSHCURRENTINPUTINDEX), and input 0 must have been spent through the\n  // Endpoint.send() Arkade closure with the Endpoint control singleton.\n  function consume() {\n    // (1) the marker is at the expected input position.\n    require(this.activeInputIndex == 1, \"marker input position\");\n\n    // (2) the Endpoint state input was spent through the Endpoint.send() closure.\n    require(\n      tx.inputs[0].arkadeScriptHash == endpointSendScriptHash,\n      \"endpoint state not via send closure\"\n    );\n\n    // (3) defense-in-depth: Endpoint control singleton on the consuming input.\n    require(\n      tx.inputs[0].assets.lookup(endpointCtrlAssetIdTxid, endpointCtrlAssetIdGidx) == 1,\n      \"endpoint state input missing control asset\"\n    );\n  }\n}\n";

export const nft_mint = "// NFT Mint Contract\n// Demonstrates fresh-issuance enforcement and collection control via asset\n// group introspection.\n//\n// An Asset ID is the canonical pair (asset_txid, asset_gidx):\n// - group.isFresh: asset issued in this tx (genesis)\n// - group.delta: net change across inputs/outputs\n// - group.controlIs(txid, gidx): collection control membership\n\nimport \"single_sig.ark\";\n\ncontract NFTMint(\n    bytes32 collectionCtrlIdTxid,\n    int collectionCtrlIdGidx,\n    pubkey issuerPk,\n    int exit\n) {\n    // Mint a new NFT: must be fresh with delta=1\n    function mint(bytes32 nftAssetIdTxid, int nftAssetIdGidx, pubkey recipientPk, signature issuerSig) {\n        let nftGroup = tx.assetGroups.find(nftAssetIdTxid, nftAssetIdGidx);\n\n        // Must be a brand new asset (genesis in this tx)\n        require(nftGroup.isFresh == 1, \"must be fresh\");\n\n        // Must mint exactly 1 (NFT)\n        require(nftGroup.delta == 1, \"must mint exactly 1\");\n\n        // Must be controlled by the collection\n        require(nftGroup.controlIs(collectionCtrlIdTxid, collectionCtrlIdGidx), \"wrong collection\");\n\n        // Control asset must be retained (delta == 0)\n        let ctrlGroup = tx.assetGroups.find(collectionCtrlIdTxid, collectionCtrlIdGidx);\n        require(ctrlGroup.delta == 0, \"control must be retained\");\n\n        // NFT goes to recipient\n        require(tx.outputs[0].assets.lookup(nftAssetIdTxid, nftAssetIdGidx) == 1, \"NFT not in output\");\n        require(tx.outputs[0].scriptPubKey == new SingleSig(recipientPk, exit), \"wrong recipient\");\n\n        require(checkSig(issuerSig, issuerPk), \"bad issuer sig\");\n    }\n\n    // Transfer existing NFT (not fresh)\n    function transfer(bytes32 nftAssetIdTxid, int nftAssetIdGidx, pubkey newOwnerPk, signature ownerSig, pubkey ownerPk) {\n        let nftGroup = tx.assetGroups.find(nftAssetIdTxid, nftAssetIdGidx);\n\n        // Must NOT be fresh (existing asset)\n        require(nftGroup.isFresh == 0, \"cannot be fresh\");\n\n        // Must be a transfer (delta == 0)\n        require(nftGroup.delta == 0, \"must be transfer\");\n\n        // Must be controlled by the collection\n        require(nftGroup.controlIs(collectionCtrlIdTxid, collectionCtrlIdGidx), \"wrong collection\");\n\n        // NFT goes to new owner\n        require(tx.outputs[0].assets.lookup(nftAssetIdTxid, nftAssetIdGidx) == 1, \"NFT not in output\");\n        require(tx.outputs[0].scriptPubKey == new SingleSig(newOwnerPk, exit), \"wrong dest\");\n\n        require(checkSig(ownerSig, ownerPk), \"bad owner sig\");\n    }\n\n    // Burn an NFT (delta = -1)\n    function burn(bytes32 nftAssetIdTxid, int nftAssetIdGidx, signature ownerSig, pubkey ownerPk) {\n        let nftGroup = tx.assetGroups.find(nftAssetIdTxid, nftAssetIdGidx);\n\n        // Must be existing asset\n        require(nftGroup.isFresh == 0, \"cannot burn fresh asset\");\n\n        // Must burn exactly 1 (negative delta)\n        require(nftGroup.sumInputs >= nftGroup.sumOutputs + 1, \"must burn exactly 1\");\n\n        require(checkSig(ownerSig, ownerPk), \"bad owner sig\");\n    }\n}\n";

export const non_interactive_swap = "// Non-Interactive Swap Contract\n// Allows users to exchange assets without requiring both parties to be online simultaneously.\n//\n// Paths:\n// - swap cooperative: takerSig + serverSig + OP_INSPECT* (trustless via introspection)\n// - cancel cooperative: makerSig + serverSig + after(expiration)\n// - unilateral: makerSig + CSV (maker recovers if no taker)\n\nimport \"single_sig.ark\";\n\ncontract NonInteractiveSwap(\n  // Maker's public key (creator of the swap offer)\n  pubkey makerPk,\n  // Asset ID the maker is offering (locked in this contract)\n  bytes32 offerAssetIdTxid,\n  int offerAssetIdGidx,\n  // Amount of offer asset locked\n  int offerAmount,\n  // Asset ID the maker wants to receive\n  bytes32 wantAssetIdTxid,\n  int wantAssetIdGidx,\n  // Amount of want asset required for the swap\n  int wantAmount,\n  // Expiration timestamp (block height) after which maker can cancel\n  int expirationTime,\n  // Exit timelock in blocks\n  int exit\n) {\n  // Swap: Any taker can fulfill - introspection makes cooperative path trustless\n  function swap(pubkey takerPk, signature takerSig) {\n    // Taker must sign to authorize spending their wantAsset\n    require(checkSig(takerSig, takerPk), \"invalid taker signature\");\n\n    // Introspection verifies the atomic exchange:\n    // Output 0: maker receives wantAsset\n    require(\n      tx.outputs[0].assets.lookup(wantAssetIdTxid, wantAssetIdGidx) >= wantAmount,\n      \"insufficient want asset for maker\"\n    );\n    require(\n      tx.outputs[0].scriptPubKey == new SingleSig(makerPk, exit),\n      \"output 0 not spendable by maker\"\n    );\n\n    // Output 1: taker receives offerAsset\n    require(\n      tx.outputs[1].assets.lookup(offerAssetIdTxid, offerAssetIdGidx) >= offerAmount,\n      \"insufficient offer asset for taker\"\n    );\n    require(\n      tx.outputs[1].scriptPubKey == new SingleSig(takerPk, exit),\n      \"output 1 not spendable by taker\"\n    );\n  }\n\n  // Cancel: Maker reclaims after expiration if no taker\n  function cancel(signature makerSig) {\n    require(tx.time >= expirationTime, \"swap not expired\");\n    require(checkSig(makerSig, makerPk), \"invalid maker signature\");\n  }\n\n  // Unilateral exit (CSV): maker recovers after exit delay.\n  function unilateral(signature makerSig) tapscript {\n    require(older(exit));\n    require(checkSig(makerSig, makerPk));\n  }\n}\n";

export const cash_secured_put = "// CashSecuredPut Contract\n//\n// Bitcoin-native, single-locked, physically-settled European cash-secured\n// put. Mirror of CoveredCall. Faithful match to Rysk Finance v12.\n//\n// Single-sided collateral lockup:\n//   - Seller locks `stableAmount` of `stableAssetId` (the cash backing\n//     for buying BTC at strike if the buyer exercises).\n//   - Buyer locks NOTHING upfront. The BTC delivery to the seller's\n//     address happens only IF the buyer chooses to exercise.\n//   - Premium flows MM->seller off-contract in the funding transaction.\n//\n// Exercise at the buyer's option:\n//   - In `[expiryHeight, expiryHeight + graceBlocks)`, the buyer may\n//     exercise by submitting a transaction that delivers `btcSats` BTC\n//     to the seller and takes the `stableAmount` stablecoin.\n//   - A rational buyer exercises iff in-the-money (spot < strike); if\n//     out-of-the-money they walk away, forfeiting only the premium.\n//   - If the buyer doesn't exercise within the grace window, the seller\n//     reclaims the cash via `reclaim()`. Buyer's failure to exercise =\n//     seller keeps the stable for free at the cost of one premium already\n//     received.\n//\n// No oracle. Buyer's exercise decision is the settlement signal.\n//\n// Transaction layout for exercise:\n//   input[0]:   this CashSecuredPut UTXO   (stableAmount of stableAssetId)\n//   input[1+]:  buyer's BTC inputs         (>= btcSats + buyer's BTC fee)\n//   output[0]:  seller receives BTC       (btcSats BTC, locked to sellerPk)\n//   output[1]:  buyer receives stable      (stableAmount of stableAssetId, locked to buyerPk)\n//   output[2+]: buyer's BTC change         (unconstrained)\n//\n// Transfer functions allow either party to reassign their leg before\n// expiry. The vault holds only the stablecoin, so the continuation\n// output preserves the stablecoin asset balance (not BTC value).\n\nimport \"single_sig.ark\";\n\ncontract CashSecuredPut(\n  pubkey  sellerPk,         // option writer; locks the stable\n  pubkey  buyerPk,          // option holder\n  bytes32 stableAssetIdTxid, // USDT / USDC asset id (issuance txid)\n  int     stableAssetIdGidx, // USDT / USDC asset id (issuance group index)\n  int     stableAmount,     // seller's deposit (strike value)\n  int     btcSats,          // BTC the buyer must deliver to exercise\n  int     expiryHeight,     // exercise window opens at this block height\n  int     graceBlocks,      // length of the exercise window in blocks\n  int     exit              // exit timelock in blocks\n) {\n\n  // -------------------------------------------------------------------------\n  // EXERCISE\n  // Buyer exercises by delivering `btcSats` BTC to the seller and taking\n  // the locked stablecoin.\n  // -------------------------------------------------------------------------\n  function exercise(signature buyerSig) {\n    require(tx.time >= expiryHeight, \"before expiry\");\n    require(checkSig(buyerSig, buyerPk), \"invalid buyer sig\");\n\n    // Output 0: seller receives the BTC.\n    require(tx.outputs[0].value >= btcSats, \"seller underpaid\");\n    require(\n      tx.outputs[0].scriptPubKey == new SingleSig(sellerPk, exit),\n      \"output 0 not seller\"\n    );\n\n    // Output 1: buyer receives the stablecoin.\n    require(\n      tx.outputs[1].assets.lookup(stableAssetIdTxid, stableAssetIdGidx) >= stableAmount,\n      \"buyer underpaid\"\n    );\n    require(\n      tx.outputs[1].scriptPubKey == new SingleSig(buyerPk, exit),\n      \"output 1 not buyer\"\n    );\n  }\n\n  // -------------------------------------------------------------------------\n  // RECLAIM\n  // Seller takes the stablecoin back once the grace window closes.\n  // -------------------------------------------------------------------------\n  function reclaim(signature sellerSig) {\n    int reclaimHeight = expiryHeight + graceBlocks;\n    require(tx.time >= reclaimHeight, \"reclaim window not open\");\n    require(checkSig(sellerSig, sellerPk), \"invalid seller sig\");\n  }\n\n  // -------------------------------------------------------------------------\n  // TRANSFER_SELLER\n  // Pre-expiry only. Writer re-assigns the short leg to a new seller.\n  // Stablecoin collateral preserved on the continuation output.\n  // -------------------------------------------------------------------------\n  function transferSeller(signature sellerSig, pubkey newSellerPk) {\n    require(tx.time < expiryHeight, \"no transfers after expiry\");\n    require(checkSig(sellerSig, sellerPk), \"invalid seller sig\");\n    require(\n      tx.outputs[0].scriptPubKey == new CashSecuredPut(\n        newSellerPk, buyerPk, stableAssetIdTxid, stableAssetIdGidx,\n        stableAmount, btcSats, expiryHeight, graceBlocks, exit\n      ),\n      \"invalid transfer output\"\n    );\n    require(\n      tx.outputs[0].assets.lookup(stableAssetIdTxid, stableAssetIdGidx) >= stableAmount,\n      \"collateral not preserved\"\n    );\n  }\n\n  // -------------------------------------------------------------------------\n  // TRANSFER_BUYER\n  // Pre-expiry only. Holder re-assigns the long leg to a new buyer.\n  // Stablecoin collateral preserved on the continuation output.\n  // -------------------------------------------------------------------------\n  function transferBuyer(signature buyerSig, pubkey newBuyerPk) {\n    require(tx.time < expiryHeight, \"no transfers after expiry\");\n    require(checkSig(buyerSig, buyerPk), \"invalid buyer sig\");\n    require(\n      tx.outputs[0].scriptPubKey == new CashSecuredPut(\n        sellerPk, newBuyerPk, stableAssetIdTxid, stableAssetIdGidx,\n        stableAmount, btcSats, expiryHeight, graceBlocks, exit\n      ),\n      \"invalid transfer output\"\n    );\n    require(\n      tx.outputs[0].assets.lookup(stableAssetIdTxid, stableAssetIdGidx) >= stableAmount,\n      \"collateral not preserved\"\n    );\n  }\n\n  // -------------------------------------------------------------------------\n  // UNILATERAL EXIT (CSV)\n  // Seller recovers locked stablecoin after exit delay (Arkade operator offline).\n  // -------------------------------------------------------------------------\n  function unilateral(signature sellerSig) tapscript {\n    require(older(exit));\n    require(checkSig(sellerSig, sellerPk));\n  }\n}\n";

export const covered_call = "// CoveredCall Contract\n//\n// Bitcoin-native, single-locked, physically-settled European covered\n// call. Faithful match to Rysk Finance v12:\n//   https://docs.rysk.finance/getting-started/protocol-and-product/how-it-works\n//\n// Single-sided collateral lockup:\n//   - Seller locks `btcSats` of BTC.\n//   - Buyer locks NOTHING upfront. The strike payment in stablecoin is\n//     transferred to the seller's address only IF the buyer chooses to\n//     exercise at expiry.\n//   - Premium flows MM->seller off-contract in the funding transaction.\n//\n// Exercise at the buyer's option:\n//   - In `[expiryHeight, expiryHeight + graceBlocks)`, the buyer may\n//     exercise by submitting a transaction that pays `strikeAmount` of\n//     `stableAssetId` to the seller and takes `btcSats` BTC.\n//   - A rational buyer exercises iff in-the-money (spot > strike); if\n//     out-of-the-money they walk away, forfeiting only the premium they\n//     already paid at funding.\n//   - If the buyer doesn't exercise within the grace window (including\n//     the case where they should have but didn't), the seller reclaims\n//     the BTC via `reclaim()`. Buyer's failure to exercise = seller\n//     keeps the BTC for free at the cost of one premium they already\n//     received.\n//\n// No oracle. The buyer's exercise decision IS the settlement signal.\n//\n// Transaction layout for exercise:\n//   input[0]:   this CoveredCall UTXO    (btcSats BTC)\n//   input[1+]:  buyer's stablecoin inputs  (>= strikeAmount + buyer's BTC fee)\n//   output[0]:  seller receives strike    (strikeAmount of stableAssetId, locked to sellerPk)\n//   output[1]:  buyer receives BTC        (btcSats BTC, locked to buyerPk)\n//   output[2+]: buyer's stablecoin change (unconstrained)\n//\n// Transfer functions allow either party to reassign their leg before\n// expiry. The vault holds only BTC, so the continuation output preserves\n// just the BTC value.\n\nimport \"single_sig.ark\";\n\ncontract CoveredCall(\n  pubkey  sellerPk,         // option writer; locks the BTC\n  pubkey  buyerPk,          // option holder\n  bytes32 stableAssetIdTxid, // USDT / USDC asset id (issuance txid)\n  int     stableAssetIdGidx, // USDT / USDC asset id (issuance group index)\n  int     btcSats,          // seller's deposit\n  int     strikeAmount,     // total stablecoin the buyer must pay to exercise\n  int     expiryHeight,     // exercise window opens at this block height\n  int     graceBlocks,      // length of the exercise window in blocks\n  int     exit              // exit timelock in blocks\n) {\n\n  // -------------------------------------------------------------------------\n  // EXERCISE\n  // Buyer exercises by paying `strikeAmount` of `stableAssetId` to seller\n  // and receiving the locked BTC.\n  // -------------------------------------------------------------------------\n  function exercise(signature buyerSig) {\n    require(tx.time >= expiryHeight, \"before expiry\");\n    require(checkSig(buyerSig, buyerPk), \"invalid buyer sig\");\n\n    // Output 0: seller receives the strike payment in stablecoin.\n    require(\n      tx.outputs[0].assets.lookup(stableAssetIdTxid, stableAssetIdGidx) >= strikeAmount,\n      \"seller underpaid\"\n    );\n    require(\n      tx.outputs[0].scriptPubKey == new SingleSig(sellerPk, exit),\n      \"output 0 not seller\"\n    );\n\n    // Output 1: buyer receives the BTC collateral.\n    require(tx.outputs[1].value >= btcSats, \"buyer underpaid\");\n    require(\n      tx.outputs[1].scriptPubKey == new SingleSig(buyerPk, exit),\n      \"output 1 not buyer\"\n    );\n  }\n\n  // -------------------------------------------------------------------------\n  // RECLAIM\n  // Seller takes the BTC back once the grace window closes.\n  // -------------------------------------------------------------------------\n  function reclaim(signature sellerSig) {\n    int reclaimHeight = expiryHeight + graceBlocks;\n    require(tx.time >= reclaimHeight, \"reclaim window not open\");\n    require(checkSig(sellerSig, sellerPk), \"invalid seller sig\");\n  }\n\n  // -------------------------------------------------------------------------\n  // TRANSFER_SELLER\n  // Pre-expiry only. Writer re-assigns the short leg to a new seller.\n  // BTC collateral preserved on the continuation output.\n  // -------------------------------------------------------------------------\n  function transferSeller(signature sellerSig, pubkey newSellerPk) {\n    require(tx.time < expiryHeight, \"no transfers after expiry\");\n    require(checkSig(sellerSig, sellerPk), \"invalid seller sig\");\n    require(\n      tx.outputs[0].scriptPubKey == new CoveredCall(\n        newSellerPk, buyerPk, stableAssetIdTxid, stableAssetIdGidx,\n        btcSats, strikeAmount, expiryHeight, graceBlocks, exit\n      ),\n      \"invalid transfer output\"\n    );\n    require(tx.outputs[0].value >= btcSats, \"collateral not preserved\");\n  }\n\n  // -------------------------------------------------------------------------\n  // TRANSFER_BUYER\n  // Pre-expiry only. Holder re-assigns the long leg to a new buyer.\n  // BTC collateral preserved on the continuation output.\n  // -------------------------------------------------------------------------\n  function transferBuyer(signature buyerSig, pubkey newBuyerPk) {\n    require(tx.time < expiryHeight, \"no transfers after expiry\");\n    require(checkSig(buyerSig, buyerPk), \"invalid buyer sig\");\n    require(\n      tx.outputs[0].scriptPubKey == new CoveredCall(\n        sellerPk, newBuyerPk, stableAssetIdTxid, stableAssetIdGidx,\n        btcSats, strikeAmount, expiryHeight, graceBlocks, exit\n      ),\n      \"invalid transfer output\"\n    );\n    require(tx.outputs[0].value >= btcSats, \"collateral not preserved\");\n  }\n\n  // -------------------------------------------------------------------------\n  // UNILATERAL EXIT (CSV)\n  // Seller recovers locked BTC after exit delay (Arkade operator offline).\n  // -------------------------------------------------------------------------\n  function unilateral(signature sellerSig) tapscript {\n    require(older(exit));\n    require(checkSig(sellerSig, sellerPk));\n  }\n}\n";

export const payment_auth = "// Payment Authorization Contract\n// Authorization-based escrow with timelocked refunds using transaction introspection\n//\n// This contract implements a credit card-like payment flow:\n// 1. Customer locks funds in escrow\n// 2. Merchant can capture (authorize and settle) the payment\n// 3. If not captured, customer can refund after timelock expires\n//\n// The contract validates the full payout structure:\n// - Merchant receives payment minus processor fee\n// - Processor receives fee (basis points of payment)\n// - Customer receives change if overpayment\n\ncontract PaymentAuthorization(\n  // Payment terms\n  int invoiceAmount,\n  int feeRateBasisPoints,\n\n  // Output scripts (P2TR scriptPubKeys)\n  bytes merchantScript,\n  bytes processorScript,\n  bytes customerScript,\n\n  // Refund timelock (block height)\n  int refundBlockHeight,\n\n  // Authorization key\n  pubkey merchantPubkey,\n\n  // Exit timelock in blocks\n  int exit\n) {\n\n  // Capture: merchant-authorized settlement\n  // Validates payout structure based on payment amount vs invoice\n  function capture(signature merchantSig) {\n    require(checkSig(merchantSig, merchantPubkey), \"Invalid merchant signature\");\n\n    // Get the current input value (amount locked in escrow)\n    let vtxoValue = tx.input.current.value;\n\n    // Case 1: Underpayment (vtxoValue < invoiceAmount)\n    // Pay merchant (minus fee) + processor fee\n    if (vtxoValue < invoiceAmount) {\n      require(vtxoValue >= 10000, \"Payment below dust threshold\");\n      require(tx.numOutputs == 2, \"Expected 2 outputs for underpayment\");\n\n      // Fee = vtxoValue * feeRateBasisPoints / 10000\n      let processorFee = (vtxoValue * feeRateBasisPoints) / 10000;\n      let merchantAmount = vtxoValue - processorFee;\n\n      require(tx.outputs[0].value == merchantAmount, \"Merchant amount incorrect\");\n      require(tx.outputs[0].scriptPubKey == merchantScript, \"Merchant script incorrect\");\n\n      require(tx.outputs[1].value == processorFee, \"Processor fee incorrect\");\n      require(tx.outputs[1].scriptPubKey == processorScript, \"Processor script incorrect\");\n    }\n\n    // Case 2: Exact payment (vtxoValue == invoiceAmount)\n    // Pay merchant (minus fee) + processor fee\n    if (vtxoValue == invoiceAmount) {\n      require(tx.numOutputs == 2, \"Expected 2 outputs for exact payment\");\n\n      // Fee = invoiceAmount * feeRateBasisPoints / 10000\n      let processorFee = (invoiceAmount * feeRateBasisPoints) / 10000;\n      let merchantAmount = invoiceAmount - processorFee;\n\n      require(tx.outputs[0].value == merchantAmount, \"Merchant amount incorrect\");\n      require(tx.outputs[0].scriptPubKey == merchantScript, \"Merchant script incorrect\");\n\n      require(tx.outputs[1].value == processorFee, \"Processor fee incorrect\");\n      require(tx.outputs[1].scriptPubKey == processorScript, \"Processor script incorrect\");\n    }\n\n    // Case 3: Overpayment (vtxoValue > invoiceAmount)\n    // Pay merchant (minus fee) + processor fee + customer change\n    if (vtxoValue > invoiceAmount) {\n      require(tx.numOutputs == 3, \"Expected 3 outputs for overpayment\");\n\n      // Fee = invoiceAmount * feeRateBasisPoints / 10000\n      let processorFee = (invoiceAmount * feeRateBasisPoints) / 10000;\n      let merchantAmount = invoiceAmount - processorFee;\n      let changeAmount = vtxoValue - invoiceAmount;\n\n      require(tx.outputs[0].value == merchantAmount, \"Merchant amount incorrect\");\n      require(tx.outputs[0].scriptPubKey == merchantScript, \"Merchant script incorrect\");\n\n      require(tx.outputs[1].value == processorFee, \"Processor fee incorrect\");\n      require(tx.outputs[1].scriptPubKey == processorScript, \"Processor script incorrect\");\n\n      require(tx.outputs[2].value == changeAmount, \"Change amount incorrect\");\n      require(tx.outputs[2].scriptPubKey == customerScript, \"Change script incorrect\");\n    }\n  }\n\n  // Refund: timelocked fallback back to customer\n  // Becomes valid after refundBlockHeight - effectively anyone-can-spend into customerScript\n  function refund() {\n    require(tx.time >= refundBlockHeight, \"Refund timelock not reached\");\n\n    let vtxoValue = tx.input.current.value;\n\n    require(tx.numOutputs == 1, \"Expected 1 output for refund\");\n    require(tx.outputs[0].value == vtxoValue, \"Refund amount incorrect\");\n    require(tx.outputs[0].scriptPubKey == customerScript, \"Refund script incorrect\");\n  }\n\n  // Unilateral exit (CSV): merchant reclaims cooperatively after CSV delay.\n  // Note: customer's exit is via the refund path above; no single customer pubkey exists.\n  function unilateral(signature merchantSig) tapscript {\n    require(older(exit));\n    require(checkSig(merchantSig, merchantPubkey));\n  }\n}\n";

export const single_sig = "contract SingleSig(\n  pubkey user,\n  int exit\n) {\n  // Single signature spend path\n  function spend(signature userSig) {\n    require(checkSig(userSig, user));\n  }\n\n  // Unilateral exit (CSV).\n  function unilateral(signature userSig) tapscript {\n    require(older(exit));\n    require(checkSig(userSig, user));\n  }\n}\n";

export const stability_offer = "// StabilityOffer Contract\n//\n// Provider pre-commits BTC liquidity into a standing offer.\n// Any swap service (or direct Seeker) can claim it non-interactively by\n// supplying a fresh oracle-signed price.\n//\n// Flow:\n//   1. Provider deploys StabilityOffer with their BTC collateral.\n//   2. Taker calls take(userBTC, seekerPk, oraclePrice, oracleTime, oracleSig).\n//   3. Contract verifies the oracle signature over sha256(ticker||price||time),\n//      enforces freshness, charges takeFee to the provider, and opens a\n//      StabilityVault bound to this ticker.\n//   4. Provider calls withdraw() to reclaim unused collateral at any time.\n//\n// Fees committed at offer creation (immutable across takes), expressed in\n// basis points (1e4 scale: 100 = 1%):\n//   - takeFee:        takeFee × userBTC / 1e4 sats; rolled into the vault\n//                     when below the 330-sat dust threshold (provider\n//                     reclaims it on their exit), otherwise emitted as a\n//                     separate output.\n//   - seekerExitFee:  applied in USD as (1 − seekerExitFee/1e4) × newTargetUSD\n//                     when seekerExit settles. Propagates into every vault.\n\nimport \"stability_vault.ark\";\n\ncontract StabilityOffer(\n  pubkey  providerPk,\n  pubkey  oraclePk,\n  bytes32 ticker,              // feed identifier; propagates into every vault\n  int     fundingRatePerSec,   // signed fixed-point at scale 1e12; seeker accepts this rate on take\n  int     maxExposureBTC,\n  int     collateralRatioPct,  // min 100 logically; offer guards 50%+ here\n  int     seekerExitFee,       // basis points; propagated into every vault\n  int     takeFee,             // basis points; takeFee × userBTC / 1e4 sats paid to provider on take\n  int     exit\n) {\n\n  // -------------------------------------------------------------------------\n  // TAKE\n  // Non-interactive: no provider signature.\n  // Caller supplies oracle-signed price; contract verifies the full message,\n  // charges takeFee, and opens a StabilityVault at the attested price.\n  //\n  // Transaction layout:\n  //   input[0]:  this StabilityOffer UTXO\n  //   input[1]:  taker's BTC (userBTC sats)\n  //   output[0]: StabilityVault\n  //   output[1]: takeFee → provider           (only if takeFee > 330)\n  //   output[2]: remaining StabilityOffer     (only if partial fill)\n  // -------------------------------------------------------------------------\n  function take(\n    int       userBTC,\n    pubkey    seekerPk,\n    int       oraclePrice,\n    int       oracleTime,\n    signature oracleSig\n  ) {\n    require(userBTC > 0, \"zero deposit\");\n    require(userBTC <= maxExposureBTC, \"exceeds offer capacity\");\n    require(collateralRatioPct >= 100, \"collateral ratio below minimum\");\n    require(oraclePrice > 0, \"invalid oracle price\");\n    require(seekerExitFee >= 0, \"negative exit fee\");\n    require(seekerExitFee <= 10000, \"exit fee > 100%\");\n    require(takeFee >= 0, \"negative take fee\");\n    require(takeFee <= 10000, \"take fee > 100%\");\n\n    int oracleAge = tx.offchainTime - oracleTime;\n    require(oracleAge >= 0, \"future-dated oracle\");\n    require(oracleAge <= 600, \"stale oracle\");\n\n    let oracleMsg = sha256(ticker + oraclePrice + oracleTime);\n    require(checkSigFromStack(oracleSig, oraclePk, oracleMsg), \"invalid oracle signature\");\n\n    int targetUSD = userBTC * oraclePrice / 100000000;\n    require(targetUSD > 0, \"position too small\");\n\n    int totalCollateral       = userBTC * (100 + collateralRatioPct) / 100;\n    int takeFeeSats           = userBTC * takeFee / 10000;\n    int remainingCapacity     = maxExposureBTC - userBTC;\n    int remainingCollateral   = remainingCapacity * collateralRatioPct / 100;\n\n    if (takeFeeSats > 330) {\n      require(\n        tx.outputs[0].scriptPubKey == new StabilityVault(\n          seekerPk, providerPk, oraclePk, ticker,\n          targetUSD, totalCollateral, fundingRatePerSec, tx.offchainTime,\n          collateralRatioPct, seekerExitFee, exit\n        ),\n        \"invalid vault output\"\n      );\n      require(tx.outputs[0].value >= totalCollateral, \"insufficient vault collateral\");\n      require(tx.outputs[1].scriptPubKey == new SingleSig(providerPk, exit), \"output 1 not provider\");\n      require(tx.outputs[1].value >= takeFeeSats, \"provider underpaid take fee\");\n      if (remainingCapacity > 0) {\n        require(\n          tx.outputs[2].scriptPubKey == new StabilityOffer(\n            providerPk, oraclePk, ticker,\n            fundingRatePerSec, remainingCapacity, collateralRatioPct,\n            seekerExitFee, takeFee, exit\n          ),\n          \"invalid remaining offer\"\n        );\n        require(tx.outputs[2].value >= remainingCollateral, \"insufficient offer collateral\");\n      }\n    } else {\n      require(\n        tx.outputs[0].scriptPubKey == new StabilityVault(\n          seekerPk, providerPk, oraclePk, ticker,\n          targetUSD, totalCollateral, fundingRatePerSec, tx.offchainTime,\n          collateralRatioPct, seekerExitFee, exit\n        ),\n        \"invalid vault output\"\n      );\n      int dustVaultValue = totalCollateral + takeFeeSats;\n      require(tx.outputs[0].value >= dustVaultValue, \"insufficient vault collateral\");\n      if (remainingCapacity > 0) {\n        require(\n          tx.outputs[1].scriptPubKey == new StabilityOffer(\n            providerPk, oraclePk, ticker,\n            fundingRatePerSec, remainingCapacity, collateralRatioPct,\n            seekerExitFee, takeFee, exit\n          ),\n          \"invalid remaining offer\"\n        );\n        require(tx.outputs[1].value >= remainingCollateral, \"insufficient offer collateral\");\n      }\n    }\n  }\n\n  // -------------------------------------------------------------------------\n  // WITHDRAW — Provider reclaims unclaimed collateral from the offer.\n  // -------------------------------------------------------------------------\n  function withdraw(signature providerSig) {\n    require(checkSig(providerSig, providerPk), \"invalid provider sig\");\n  }\n\n  // -------------------------------------------------------------------------\n  // UNILATERAL EXIT (CSV)\n  // Provider recovers locked collateral after exit delay (Arkade operator offline).\n  // -------------------------------------------------------------------------\n  function unilateral(signature providerSig) tapscript {\n    require(older(exit));\n    require(checkSig(providerSig, providerPk));\n  }\n}\n";

export const stability_vault = "// StabilityVault Contract\n//\n// A USD-denominated claim backed by BTC collateral.\n// Seeker holds a fixed USD value; Provider locks additional collateral and\n// takes a leveraged BTC long. Provider pays Seeker a funding rate.\n//\n// Funding model (USD-compound):\n//   At every settlement boundary the USD claim is rolled forward:\n//     elapsed       = tx.offchainTime - lastUpdate\n//     newTargetUSD  = targetUSD × (1 + fundingRatePerSec × elapsed / 1e12)\n//   targetUSD compounds in USD terms. fundingRatePerSec is a signed\n//   fixed-point fraction at scale 1e12.\n//\n// Settlement math (single shape across settleAndUpdateFunding,\n// seekerExit, providerExit, removeCapital):\n//   newTargetUSD = targetUSD × (1 + fundingRatePerSec × elapsed / 1e12)\n//   seekerRaw    = newTargetUSD × (1 - seekerExitFee/1e4) × 1e8 / P   [seekerExit]\n//   seekerRaw    = newTargetUSD × 1e8 / P                              [providerExit]\n//   seekerPayout = clamp(seekerRaw, 0, totalCollateral)\n//   providerPayout = totalCollateral − seekerPayout\n//\n// Oracle model (Fuji-style signed price feed):\n//   Oracle off-chain produces:\n//     msg = sha256(ticker || price || timestamp)\n//     sig = sign(oraclePk, msg)\n//   where price and timestamp are 8-byte little-endian unsigned ints.\n//   At settlement the caller supplies (oraclePrice, oracleTime, oracleSig).\n//   Freshness: tx.offchainTime - oracleTime <= 600 seconds.\n\nimport \"single_sig.ark\";\n\ncontract StabilityVault(\n  pubkey  seekerPk,           // current holder of the USD claim\n  pubkey  providerPk,         // collateral provider, holds the long side\n  pubkey  oraclePk,           // only signatures from this key accepted\n  bytes32 ticker,             // feed identifier (e.g. sha256(\"BTC/USD\"))\n  int     targetUSD,          // seeker's USD claim in cents; mutates on settle\n  int     totalCollateral,    // sats locked; mutates on add/removeCapital\n  int     fundingRatePerSec,  // signed fixed-point at scale 1e12; mutates on settle\n  int     lastUpdate,         // unix seconds; basis for funding accrual\n  int     collateralRatioPct, // min collateral ratio for removeCapital (e.g. 50 = 1.5:1)\n  int     seekerExitFee,      // basis points (1e4 scale); seekerExit pays fee × targetUSD to provider\n  int     exit                // exit timelock in blocks\n) {\n\n  // -------------------------------------------------------------------------\n  // TRANSFER — pure key swap, no oracle.\n  // -------------------------------------------------------------------------\n  function transfer(signature seekerSig, pubkey newSeekerPk) {\n    require(checkSig(seekerSig, seekerPk), \"invalid seeker sig\");\n\n    require(\n      tx.outputs[0].scriptPubKey == new StabilityVault(\n        newSeekerPk, providerPk, oraclePk, ticker,\n        targetUSD, totalCollateral, fundingRatePerSec, lastUpdate,\n        collateralRatioPct, seekerExitFee, exit\n      ),\n      \"invalid transfer output\"\n    );\n    require(tx.outputs[0].value >= totalCollateral, \"collateral not preserved\");\n  }\n\n  // -------------------------------------------------------------------------\n  // SPLIT — proportional USD-claim split into two independent positions.\n  // -------------------------------------------------------------------------\n  function split(signature seekerSig, int amountUSD, pubkey newSeekerPk) {\n    require(checkSig(seekerSig, seekerPk), \"invalid seeker sig\");\n    require(amountUSD > 0, \"zero amount\");\n    require(amountUSD < targetUSD, \"amount exceeds balance\");\n\n    int remainingUSD = targetUSD - amountUSD;\n    int collateralA  = totalCollateral * amountUSD / targetUSD;\n    int collateralB  = totalCollateral - collateralA;\n\n    require(collateralA >= 330, \"split amount too small\");\n    require(collateralB >= 330, \"remainder too small\");\n\n    require(\n      tx.outputs[0].scriptPubKey == new StabilityVault(\n        newSeekerPk, providerPk, oraclePk, ticker,\n        amountUSD, collateralA, fundingRatePerSec, lastUpdate,\n        collateralRatioPct, seekerExitFee, exit\n      ),\n      \"invalid split output 0\"\n    );\n    require(tx.outputs[0].value >= collateralA, \"insufficient collateral A\");\n\n    require(\n      tx.outputs[1].scriptPubKey == new StabilityVault(\n        seekerPk, providerPk, oraclePk, ticker,\n        remainingUSD, collateralB, fundingRatePerSec, lastUpdate,\n        collateralRatioPct, seekerExitFee, exit\n      ),\n      \"invalid split output 1\"\n    );\n    require(tx.outputs[1].value >= collateralB, \"insufficient collateral B\");\n  }\n\n  // -------------------------------------------------------------------------\n  // MERGE — Seeker combines two of their own vaults into one.\n  // -------------------------------------------------------------------------\n  function merge(\n    signature seekerSig,\n    int       otherIdx,\n    int       otherTargetUSD,\n    int       otherTotalCollateral,\n    int       otherFundingRatePerSec,\n    int       otherLastUpdate,\n    int       otherSeekerExitFee,\n    int       mergedFundingRatePerSec,\n    int       mergedSeekerExitFee\n  ) {\n    require(checkSig(seekerSig, seekerPk), \"invalid seeker sig\");\n    require(this.activeInputIndex != otherIdx, \"self-merge disallowed\");\n\n    require(\n      tx.inputs[otherIdx].scriptPubKey == new StabilityVault(\n        seekerPk, providerPk, oraclePk, ticker,\n        otherTargetUSD, otherTotalCollateral, otherFundingRatePerSec, otherLastUpdate,\n        collateralRatioPct, otherSeekerExitFee, exit\n      ),\n      \"input not matching vault\"\n    );\n\n    if (fundingRatePerSec >= otherFundingRatePerSec) {\n      require(mergedFundingRatePerSec == fundingRatePerSec, \"merged rate != max\");\n    } else {\n      require(mergedFundingRatePerSec == otherFundingRatePerSec, \"merged rate != max\");\n    }\n\n    if (seekerExitFee >= otherSeekerExitFee) {\n      require(mergedSeekerExitFee == seekerExitFee, \"merged exit fee != max\");\n    } else {\n      require(mergedSeekerExitFee == otherSeekerExitFee, \"merged exit fee != max\");\n    }\n\n    int elapsedA      = tx.offchainTime - lastUpdate;\n    require(elapsedA >= 0, \"clock regression A\");\n    int rateElapsedA  = fundingRatePerSec * elapsedA / 1000000;\n    int deltaA        = targetUSD * rateElapsedA / 1000000;\n    int accruedA      = targetUSD + deltaA;\n\n    int elapsedB      = tx.offchainTime - otherLastUpdate;\n    require(elapsedB >= 0, \"clock regression B\");\n    int rateElapsedB  = otherFundingRatePerSec * elapsedB / 1000000;\n    int deltaB        = otherTargetUSD * rateElapsedB / 1000000;\n    int accruedB      = otherTargetUSD + deltaB;\n\n    int mergedTargetUSD       = accruedA + accruedB;\n    int mergedTotalCollateral = totalCollateral + otherTotalCollateral;\n\n    require(\n      tx.outputs[0].scriptPubKey == new StabilityVault(\n        seekerPk, providerPk, oraclePk, ticker,\n        mergedTargetUSD, mergedTotalCollateral, mergedFundingRatePerSec, tx.offchainTime,\n        collateralRatioPct, mergedSeekerExitFee, exit\n      ),\n      \"invalid merged vault output\"\n    );\n    require(tx.outputs[0].value >= mergedTotalCollateral, \"merged collateral underfunded\");\n  }\n\n  // -------------------------------------------------------------------------\n  // SETTLE & UPDATE FUNDING\n  // -------------------------------------------------------------------------\n  function settleAndUpdateFunding(signature providerSig, int newFundingRatePerSec) {\n    require(checkSig(providerSig, providerPk), \"invalid provider sig\");\n    require(newFundingRatePerSec >= 0, \"negative funding rate disallowed\");\n\n    int elapsed           = tx.offchainTime - lastUpdate;\n    require(elapsed >= 0, \"clock regression\");\n    int rateElapsedScaled = fundingRatePerSec * elapsed / 1000000;\n    int delta             = targetUSD * rateElapsedScaled / 1000000;\n    int newTargetUSD      = targetUSD + delta;\n    require(newTargetUSD > 0, \"claim wiped by funding\");\n\n    if (fundingRatePerSec != 0) {\n      require(delta > 0, \"no accrual; wait longer\");\n    }\n\n    require(\n      tx.outputs[0].scriptPubKey == new StabilityVault(\n        seekerPk, providerPk, oraclePk, ticker,\n        newTargetUSD, totalCollateral, newFundingRatePerSec, tx.offchainTime,\n        collateralRatioPct, seekerExitFee, exit\n      ),\n      \"invalid settle output\"\n    );\n    require(tx.outputs[0].value >= totalCollateral, \"collateral not preserved\");\n  }\n\n  // -------------------------------------------------------------------------\n  // ADD CAPITAL — Provider tops up collateral.\n  // -------------------------------------------------------------------------\n  function addCapital(signature providerSig, int amount) {\n    require(checkSig(providerSig, providerPk), \"invalid provider sig\");\n    require(amount > 0, \"zero amount\");\n\n    int newTotalCollateral = totalCollateral + amount;\n\n    require(\n      tx.outputs[0].scriptPubKey == new StabilityVault(\n        seekerPk, providerPk, oraclePk, ticker,\n        targetUSD, newTotalCollateral, fundingRatePerSec, lastUpdate,\n        collateralRatioPct, seekerExitFee, exit\n      ),\n      \"invalid output\"\n    );\n    require(tx.outputs[0].value >= newTotalCollateral, \"collateral not deposited\");\n  }\n\n  // -------------------------------------------------------------------------\n  // REMOVE CAPITAL — Provider reclaims excess collateral.\n  // -------------------------------------------------------------------------\n  function removeCapital(\n    signature providerSig,\n    int       amount,\n    int       oraclePrice,\n    int       oracleTime,\n    signature oracleSig\n  ) {\n    require(checkSig(providerSig, providerPk), \"invalid provider sig\");\n    require(amount > 0, \"zero amount\");\n    require(oraclePrice > 0, \"invalid oracle price\");\n\n    int oracleAge = tx.offchainTime - oracleTime;\n    require(oracleAge >= 0, \"future-dated oracle\");\n    require(oracleAge <= 600, \"stale oracle\");\n\n    let oracleMsg = sha256(ticker + oraclePrice + oracleTime);\n    require(checkSigFromStack(oracleSig, oraclePk, oracleMsg), \"invalid oracle signature\");\n\n    int elapsed           = tx.offchainTime - lastUpdate;\n    require(elapsed >= 0, \"clock regression\");\n    int rateElapsedScaled = fundingRatePerSec * elapsed / 1000000;\n    int delta             = targetUSD * rateElapsedScaled / 1000000;\n    int newTargetUSD      = targetUSD + delta;\n    int currentSeekerBase = newTargetUSD * 100000000 / oraclePrice;\n    int minCollateral     = currentSeekerBase * (100 + collateralRatioPct) / 100;\n    int newTotalCollateral = totalCollateral - amount;\n    require(newTotalCollateral >= minCollateral, \"would breach collateral ratio\");\n\n    require(\n      tx.outputs[0].scriptPubKey == new StabilityVault(\n        seekerPk, providerPk, oraclePk, ticker,\n        targetUSD, newTotalCollateral, fundingRatePerSec, lastUpdate,\n        collateralRatioPct, seekerExitFee, exit\n      ),\n      \"invalid vault output\"\n    );\n    require(tx.outputs[0].value >= newTotalCollateral, \"vault underfunded\");\n    require(tx.outputs[1].scriptPubKey == new SingleSig(providerPk, exit), \"output 1 not provider\");\n    require(tx.outputs[1].value >= amount, \"provider underpaid\");\n  }\n\n  // -------------------------------------------------------------------------\n  // SEEKER EXIT — Seeker exits to BTC at the oracle-attested price.\n  // -------------------------------------------------------------------------\n  function seekerExit(\n    signature seekerSig,\n    int       oraclePrice,\n    int       oracleTime,\n    signature oracleSig\n  ) {\n    require(checkSig(seekerSig, seekerPk), \"invalid seeker sig\");\n    require(oraclePrice > 0, \"invalid oracle price\");\n\n    int oracleAge = tx.offchainTime - oracleTime;\n    require(oracleAge >= 0, \"future-dated oracle\");\n    require(oracleAge <= 600, \"stale oracle\");\n\n    let oracleMsg = sha256(ticker + oraclePrice + oracleTime);\n    require(checkSigFromStack(oracleSig, oraclePk, oracleMsg), \"invalid oracle signature\");\n\n    int elapsed           = tx.offchainTime - lastUpdate;\n    require(elapsed >= 0, \"clock regression\");\n    int rateElapsedScaled = fundingRatePerSec * elapsed / 1000000;\n    int delta             = targetUSD * rateElapsedScaled / 1000000;\n    int newTargetUSD      = targetUSD + delta;\n    int netTargetUSD      = newTargetUSD * (10000 - seekerExitFee) / 10000;\n    int seekerRaw         = netTargetUSD * 100000000 / oraclePrice;\n\n    if (seekerRaw <= 0) {\n      require(tx.outputs[0].value >= totalCollateral, \"provider underpaid\");\n      require(tx.outputs[0].scriptPubKey == new SingleSig(providerPk, exit), \"output 0 not provider\");\n    } else {\n      if (seekerRaw >= totalCollateral) {\n        require(tx.outputs[0].value >= totalCollateral, \"seeker underpaid\");\n        require(tx.outputs[0].scriptPubKey == new SingleSig(seekerPk, exit), \"output 0 not seeker\");\n      } else {\n        require(tx.outputs[0].value >= seekerRaw, \"seeker underpaid\");\n        require(tx.outputs[0].scriptPubKey == new SingleSig(seekerPk, exit), \"output 0 not seeker\");\n        int providerPayout = totalCollateral - seekerRaw;\n        if (providerPayout > 330) {\n          require(tx.outputs[1].value >= providerPayout, \"provider underpaid\");\n          require(tx.outputs[1].scriptPubKey == new SingleSig(providerPk, exit), \"output 1 not provider\");\n        }\n      }\n    }\n  }\n\n  // -------------------------------------------------------------------------\n  // PROVIDER EXIT — Identical settlement math; no exit fee charged to provider.\n  // -------------------------------------------------------------------------\n  function providerExit(\n    signature providerSig,\n    int       oraclePrice,\n    int       oracleTime,\n    signature oracleSig\n  ) {\n    require(checkSig(providerSig, providerPk), \"invalid provider sig\");\n    require(oraclePrice > 0, \"invalid oracle price\");\n\n    int oracleAge = tx.offchainTime - oracleTime;\n    require(oracleAge >= 0, \"future-dated oracle\");\n    require(oracleAge <= 600, \"stale oracle\");\n\n    let oracleMsg = sha256(ticker + oraclePrice + oracleTime);\n    require(checkSigFromStack(oracleSig, oraclePk, oracleMsg), \"invalid oracle signature\");\n\n    int elapsed           = tx.offchainTime - lastUpdate;\n    require(elapsed >= 0, \"clock regression\");\n    int rateElapsedScaled = fundingRatePerSec * elapsed / 1000000;\n    int delta             = targetUSD * rateElapsedScaled / 1000000;\n    int newTargetUSD      = targetUSD + delta;\n    int seekerRaw         = newTargetUSD * 100000000 / oraclePrice;\n\n    if (seekerRaw <= 0) {\n      require(tx.outputs[0].value >= totalCollateral, \"provider underpaid\");\n      require(tx.outputs[0].scriptPubKey == new SingleSig(providerPk, exit), \"output 0 not provider\");\n    } else {\n      if (seekerRaw >= totalCollateral) {\n        require(tx.outputs[0].value >= totalCollateral, \"seeker underpaid\");\n        require(tx.outputs[0].scriptPubKey == new SingleSig(seekerPk, exit), \"output 0 not seeker\");\n      } else {\n        require(tx.outputs[0].value >= seekerRaw, \"seeker underpaid\");\n        require(tx.outputs[0].scriptPubKey == new SingleSig(seekerPk, exit), \"output 0 not seeker\");\n        int providerPayout = totalCollateral - seekerRaw;\n        if (providerPayout > 330) {\n          require(tx.outputs[1].value >= providerPayout, \"provider underpaid\");\n          require(tx.outputs[1].scriptPubKey == new SingleSig(providerPk, exit), \"output 1 not provider\");\n        }\n      }\n    }\n  }\n\n  // -------------------------------------------------------------------------\n  // UNILATERAL EXIT (CSV)\n  // Seeker recovers after exit delay (Arkade operator offline).\n  // -------------------------------------------------------------------------\n  function unilateral(signature seekerSig) tapscript {\n    require(older(exit));\n    require(checkSig(seekerSig, seekerPk));\n  }\n}\n";

export const threshold_multisig_htlc = "contract HTLC(\n  pubkey sender,\n  pubkey receiver,\n  bytes hash,\n  int refundTime,\n  int exit\n) {\n  // Cooperative close path: both parties agree\n  function together(signature senderSig, signature receiverSig) {\n    require(checkMultisig([sender, receiver], [senderSig, receiverSig]));\n  }\n\n  // Refund path: sender reclaims after timeout\n  function refund(signature senderSig) {\n    require(checkSig(senderSig, sender));\n    require(tx.time >= refundTime);\n  }\n\n  // Claim path: receiver claims with preimage\n  function claim(signature receiverSig, bytes preimage) {\n    require(checkSig(receiverSig, receiver));\n    require(sha256(preimage) == hash);\n  }\n\n  // Unilateral exit (CSV): sender recovers after exit delay.\n  function unilateral(signature senderSig) tapscript {\n    require(older(exit));\n    require(checkSig(senderSig, sender));\n  }\n}\n";

export const threshold_oracle = "// Threshold Oracle Contract\n// Generic threshold signature verifier for multi-oracle attestations.\n//\n// This contract demonstrates:\n// - Array types in constructor params (pubkey[] oracles)\n// - Array types in function params (signature[] oracleSigs)\n// - Array indexing (oracles[i])\n// - Loop unrolling with array iteration\n// - Threshold counting for quorum verification\n//\n// N oracles, require M valid signatures over a message.\n\nimport \"single_sig.ark\";\n\ncontract ThresholdOracle(\n  bytes32 tokenAssetIdTxid,\n  int tokenAssetIdGidx,\n  bytes32 ctrlAssetIdTxid,\n  int ctrlAssetIdGidx,\n  pubkey[] oracles,\n  int threshold,\n  int exit\n) {\n  function attest(\n    int amount,\n    bytes32 messageHash,\n    pubkey recipientPk,\n    signature[] oracleSigs\n  ) {\n    require(amount > 0, \"zero\");\n\n    int valid = 0;\n    for (i, sig) in oracleSigs {\n      if (checkSigFromStack(sig, oracles[i], messageHash)) {\n        valid = valid + 1;\n      }\n    }\n    require(valid >= threshold, \"quorum failed\");\n\n    require(tx.inputs[0].assets.lookup(ctrlAssetIdTxid, ctrlAssetIdGidx) > 0, \"no ctrl\");\n    require(tx.outputs[1].assets.lookup(tokenAssetIdTxid, tokenAssetIdGidx) >= amount, \"short\");\n    require(tx.outputs[1].scriptPubKey == new SingleSig(recipientPk, exit), \"wrong dest\");\n    require(tx.outputs[0].scriptPubKey == new ThresholdOracle(tokenAssetIdTxid, tokenAssetIdGidx, ctrlAssetIdTxid, ctrlAssetIdGidx, oracles, threshold, exit), \"broken\");\n  }\n}\n";

export const token_vault = "// Token Vault Contract\n// Demonstrates asset lookup primitives for Arkades Assets\n//\n// This contract locks tokens and allows:\n// 1. deposit() - Owner deposits tokens; output must hold at least as many as input\n// 2. withdraw() - Owner withdraws tokens with server co-signature\n//\n// Uses asset lookups on tx.inputs and tx.outputs with arithmetic\n// comparisons for balance verification.\n\ncontract TokenVault(\n  pubkey ownerPk,\n  bytes32 tokenAssetIdTxid,\n  int tokenAssetIdGidx,\n  bytes32 ctrlAssetIdTxid,\n  int ctrlAssetIdGidx,\n  int exit\n) {\n  // Deposit: ensure the control asset stays in the output\n  // and output token balance >= input token balance\n  function deposit(signature ownerSig) {\n    // Control asset must be present in input 0\n    require(tx.inputs[0].assets.lookup(ctrlAssetIdTxid, ctrlAssetIdGidx) > 0, \"no ctrl in input\");\n\n    // Control asset must be present in output 0\n    require(tx.outputs[0].assets.lookup(ctrlAssetIdTxid, ctrlAssetIdGidx) > 0, \"no ctrl in output\");\n\n    // Output tokens >= input tokens (no leaking tokens)\n    require(\n      tx.outputs[0].assets.lookup(tokenAssetIdTxid, tokenAssetIdGidx) >=\n        tx.inputs[0].assets.lookup(tokenAssetIdTxid, tokenAssetIdGidx),\n      \"token balance decreased\"\n    );\n\n    // Owner must sign\n    require(checkSig(ownerSig, ownerPk), \"invalid owner signature\");\n  }\n\n  // Withdraw: owner withdraws tokens cooperatively with server\n  function withdraw(signature ownerSig, int amount) {\n    // Control asset must stay in the output\n    require(tx.outputs[0].assets.lookup(ctrlAssetIdTxid, ctrlAssetIdGidx) > 0, \"no ctrl in output\");\n\n    // Owner must sign\n    require(checkSig(ownerSig, ownerPk), \"invalid owner signature\");\n  }\n\n  // Unilateral exit (CSV): owner recovers after exit delay.\n  function unilateral(signature ownerSig) tapscript {\n    require(older(exit));\n    require(checkSig(ownerSig, ownerPk));\n  }\n}\n";

